(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-asr-quant-edge"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-1\">一 · 事故现场：实时率达标了，识别却塌了</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-2\">二 · 它解决的推理问题：带宽与算力，而不是模型能力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-3\">三 · 机制顺序：从校准到反量化的五步链条</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-4\">四 · 它不解决什么：三条边界要写进设计文档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-5\">五 · 适用性判据：什么时候该上，什么时候不该上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-6\">六 · 把边界写进校准与精度分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-7\">七 · 量化在噪声段失效：一个端侧流式识别事故的解剖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-8\">八 · 校准前向：把动态范围变成逐通道缩放因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-9\">九 · 权重离线量化与异常值通道保留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-10\">十 · 激活在线量化与低比特矩阵乘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-11\">十一 · 解码器 KV cache 低比特存储与滚动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-12\">十二 · 反量化输出、流式拼接与端到端代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-13\">十三 · 帧块流水上的量化边界：从校准到流式解码的失效链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-14\">十四 · 逐通道缩放的推导起点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-15\">十五 · 激活在线量化的伪代码与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-16\">十六 · 异常值保留的判定与混合精度分支</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-17\">十七 · KV cache 低比特存储的误差累积推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-18\">十八 · 校准与前向统计的可实现流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-19\">十九 · 比特数、指令与实时率的联合取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-20\">二十 · 请求形态决定量化收益的形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-21\">二十一 · 批大小与并发：小批是延迟约束下的必然，也是量化误差的放大器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-22\">二十二 · 长度分布与 KV cache 滚动：长语音是配方失效的第一现场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-23\">二十三 · 异常值通道与 INT4：配方在比特数上的分档判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-24\">二十四 · 校准集与真实分布的错配：配方失效的根因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-25\">二十五 · 配方的工程判断：形态、长度、批、位宽四者对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-26\">二十六 · 硬件档位与指令路径的选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-27\">二十七 · 并行拓扑：编码器与解码器的流水切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-28\">二十八 · 量化方案的组合与异常值处理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-29\">二十九 · KV 策略：滚动窗口与块级淘汰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-30\">三十 · 调度参数与可复现配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-31\">三十一 · 配方失效的三个边界：校准漂移、KV 累积误差与 INT4 异常值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-32\">三十二 · 显存墙：权重、KV cache 与滚动窗口的三方挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-33\">三十三 · 带宽：低比特真正买到的是读带宽，不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-34\">三十四 · 通信：端侧单流拓扑下，通信代价藏在流水边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-35\">三十五 · 功耗：比特数、激活量化开销与实时率的三角</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-36\">三十六 · 尾延迟：规模上去以后第一个崩的是它</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-37\">三十七 · 规模上限的工程判断：先保准确率方差，再谈比特数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-38\">三十八 · 规模上去以后，先崩的是解码 KV cache 的读带宽而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-39\">三十九 · 功耗墙与异常值通道的实现税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-40\">四十 · 精度塌陷的三种形态与可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-41\">四十一 · OOM 与批抖动的耦合诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-42\">四十二 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-43\">四十三 · 监控指标体系与打点位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-44\">四十四 · 回滚策略：分级降级而非一刀切</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-45\">四十五 · 诊断闭环与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-46\">四十六 · 同族算法的选择维度：比特宽度不是唯一轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-47\">四十七 · 与 FP16 基线的对照：线性收益与非线性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-48\">四十八 · 与 SmoothQuant 类均衡方法的对照：作用点不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-49\">四十九 · 决策表：按场景条件选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-50\">五十 · 适用条件与规模上限的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-asr-quant-edge-sec-51\">五十一 · 边界判定：同族量化路线在端侧 ASR 上的取舍与失效面</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:499px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 499.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">校准集前向统计各层权重与激活的动态范围，确定逐通道缩放因子</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">权重离线量化为 INT8/INT4，异常值通道保留高精度或单独处理</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时激活在线量化，矩阵乘用低比特 Tensor Core 或 DP4A …</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码器 KV cache 同样低比特存储，减少自回归解码显存读带宽</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"417.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出反量化后送语言模型/后处理，端侧按帧块流式识别</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-asr-quant-edge-sec-1\">一 · 事故现场：实时率达标了，识别却塌了</h3>\n<p>某离线语音助手项目在 Blackwell 边缘 SKU 上做端侧 ASR 部署，FP16 编码器/解码器在目标功耗包络内跑不到目标实时率，团队按比特数近似线性下降的直觉把权重压到 INT4、激活压到 INT8，并在实验室安静环境下测得实时率与功耗双双达标。量产出货后，真实场景的投诉集中在两类：一是噪声段与带口音语音的识别准确率明显下降，二是长语音的句尾识别准确率显著低于句首。复盘发现两个独立缺陷叠加——校准集只覆盖了安静环境的标准普通话，激活动态范围估计偏窄，噪声段的激活异常值在量化时被裁掉；解码器 KV cache 的低比特存储没有做任何误差补偿，自回归解码把每步的量化误差逐步累积到句尾。实时率提升是真的，准确率劣化也是真的，而这正是低比特 ASR 边缘推理要解决、也最容易踩坏的那条边界。</p>\n<p>这个事故说明了一件事：低比特量化不是“把 FP16 换成 INT8 就完事”的格式替换，而是一个从校准集设计、异常值处理、KV cache 误差控制到指令选择的完整推理工程。本部分只界定这个算法解决什么、不解决什么，以及它在什么条件下会把实时率的收益换成准确率的代价。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-2\">二 · 它解决的推理问题：带宽与算力，而不是模型能力</h3>\n<p>问题定义很窄：语音识别模型在边缘/端侧部署时，显存与算力受限，FP16 权重与激活占用大，实时率与功耗难以满足离线语音助手的需求。端侧流式识别按帧块输入，批大小通常为 1 或小批以控制延迟，SLO 以实时率与功耗衡量——这意味着系统既没有大 batch 摊薄权重读取的余地，也没有数据中心级的功耗预算。此时推理的瓶颈通常不在浮点算力峰值，而在显存带宽：每帧块前向都要把编码器与解码器的权重从显存搬到计算单元，权重位宽直接决定搬运量。</p>\n<p>低比特量化正是对这一瓶颈的直接打击：显存占用与带宽按比特数近似线性下降，端侧因此可以跑更大模型或维持更低功耗；低比特矩阵乘在 Blackwell 边缘 SKU 上可利用低比特 Tensor Core 或 DP4A 指令提升实时率。注意这里的关键词是“带宽与算力”，不是“更聪明的模型”。量化不改变模型容量，不引入新知识，不修复声学建模本身的缺陷；它只是让同一个模型在更紧的显存与功耗约束下跑得更快。把它当作精度提升手段是方向性错误。</p>\n<p>代价一侧同样明确：激活异常值导致量化误差，需保留通道或做混合精度，增加实现复杂度；低比特解码 KV cache 可能累积误差，长语音识别准确率下降。这两条代价不是实现瑕疵，而是算法适用边界的物理来源，后文会分别展开。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-3\">三 · 机制顺序：从校准到反量化的五步链条</h3>\n<p>按数据/梯度流动顺序，机制可以拆成五步，每一步都对应一个可观测的系统代价。</p>\n<ul>\n<li><b>校准</b>：校准集前向统计各层权重与激活的动态范围，确定逐通道缩放因子。这一步决定了后续所有量化误差的上界；校准集不覆盖真实噪声与口音，激活动态范围就会估窄，噪声段误差被放大。</li>\n<li><b>权重量化</b>：权重离线量化为 INT8/INT4，异常值通道保留高精度或单独处理。离线量化不占推理时延，但异常值通道的识别与分流会增加实现复杂度。</li>\n<li><b>激活在线量化</b>：推理时对激活做在线量化，动态范围裁剪策略直接影响噪声段的稳定性；矩阵乘用低比特 Tensor Core 或 DP4A 指令执行。</li>\n<li><b>KV cache 低比特存储</b>：解码器 KV cache 同样低比特存储，减少自回归解码的显存读带宽——这是端侧单流解码最直接的收益点，也是长语音误差累积的来源。</li>\n<li><b>反量化与流式输出</b>：输出反量化后送语言模型/后处理，端侧按帧块流式识别，编码器与解码器流水、单流执行。</li>\n</ul>\n<p>核心公式是逐通道对称量化与反量化：</p>\n<div class=\"formula\">$$q=\\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{x}{s}\\big),\\,-2^{b-1},\\,2^{b-1}-1\\Big),\\quad \\hat{x}=s\\cdot q$$</div>\n<p>其中 $x$ 为权重或激活，$s$ 为逐通道缩放因子，$b$ 为比特数（INT8 时 $b=8$，INT4 时 $b=4$），$q$ 为量化整数，$\\hat{x}$ 为反量化近似值。缩放因子常取 $s=\\max|W|/(2^{b-1}-1)$，即由该通道最大幅值决定。这个式子里藏着两个工程事实：其一，$s$ 由单通道最大幅值主导，一个异常值就能把整通道的有效分辨率压窄，这正是“异常值通道保留高精度”的动机；其二，$b$ 每减 1，显存与带宽近似减半，但可表示的动态范围也减半，误差上界随之抬升。INT4 相对 INT8 的收益是带宽再省一半，代价是异常值保留从“可选优化”变成“必需项”。</p>\n<p>一个具体例子：编码器某层权重通道最大幅值远大于其余通道，若整层共用一个大缩放因子，小幅值通道大量落入同一量化格点，矩阵乘结果整体偏移；按通道分别定 $s$、并把该异常通道单独以高精度保留，才能在拿到 INT4 带宽收益的同时不让关键词识别失败率上升。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-4\">四 · 它不解决什么：三条边界要写进设计文档</h3>\n<p>第一，不解决分布外泛化。校准集与真实分布不匹配时，典型表现是实时率提升但准确率劣化——事故中的噪声段与口音正是这一类。量化误差的上界由校准分布决定，部署分布一旦漂移，误差就不再受控。校准集必须覆盖真实噪声与口音，这是稳定性技巧而非可选项。</p>\n<p>第二，不解决长语音的误差累积。解码器 KV cache 低比特存储若不做误差补偿，自回归解码每步引入的量化误差会随解码步数累积，表现为句尾识别准确率显著低于句首。长语音需按块滚动以控制显存，但滚动本身不消除累积误差；这是 KV cache 量化路径上的结构性代价，只能靠误差补偿与精度分层缓解，不能靠调参归零。</p>\n<p>第三，不替代激活-权重均衡类方法。相对 SmoothQuant 类激活-权重均衡方法，本算法侧重端侧低比特权重与 KV cache 量化，强调 DP4A/Tensor Core 指令利用与功耗约束；激活异常值若严重到均衡方法才能压平，单靠逐通道缩放与异常值保留会陷入“保留通道越多、带宽收益越小”的两难。适用边界因此是离线语音助手等端侧低功耗场景，上限受低比特量化误差与 KV cache 累积误差约束，长语音与分布外口音下准确率下降；INT4 权重需异常值保留，实现复杂度高于 INT8。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-5\">五 · 适用性判据：什么时候该上，什么时候不该上</h3>\n<p>给出三条可操作的工程判据，避免把适用边界写成口号。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>判据</th><th>倾向采用低比特</th><th>倾向维持 FP16 或混合精度</th></tr>\n</thead>\n<tbody>\n<tr><td>瓶颈位置</td><td>显存带宽与功耗主导，批大小为 1 或小批</td><td>算力峰值主导，或延迟由非矩阵乘算子主导</td></tr>\n<tr><td>语音形态</td><td>短指令、离线唤醒词、帧块流式短句</td><td>长语音转写、句尾准确率敏感</td></tr>\n<tr><td>分布可控性</td><td>校准集能覆盖真实噪声与口音</td><td>部署分布漂移大、口音长尾重</td></tr>\n</tbody>\n</table>\n<p>第一，看瓶颈。若端侧单流前向的时间主要花在权重搬运上，低比特的带宽收益按比特数近似线性兑现；若时间花在非矩阵乘算子或解码调度上，压权重位宽对实时率的边际贡献迅速衰减。第二，看语音形态。短指令场景解码步数少，KV cache 累积误差没有足够步数放大；长语音转写则相反，句尾准确率是硬约束。第三，看分布可控性。校准集覆盖真实噪声与口音是低比特方案成立的前提；覆盖不了，就该在异常值通道上保留更多高精度，或退回 INT8 甚至混合精度。</p>\n<p>系统代价的量化方式也要统一：显存占用与带宽按比特数近似线性下降，这是收益侧；实现复杂度、校准成本、异常值通道的额外高精度计算是代价侧。二者要在同一个 SLO（实时率与功耗）下比较，而不是只报实时率提升。事故项目的错误正在于只测了收益侧。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-6\">六 · 把边界写进校准与精度分层</h3>\n<p>落回机制层面：低比特 ASR 边缘推理的稳定性不来自某个开关，而来自校准集设计与精度分层的联合约束。校准阶段要按真实噪声与口音分层采样，逐层统计权重与激活动态范围，对激活异常值通道标记并保留高精度；权重侧 INT4 必须配套异常值通道识别，否则少数大幅值通道量化后矩阵乘结果偏移，实时率提升换来关键词识别失败率上升。解码器 KV cache 的低比特存储要配误差补偿，并对长语音按块滚动控制显存，把累积误差限制在可接受区间。端侧单流、编码器与解码器流水、批大小为 1 的负载形态决定了这些约束没有大 batch 的统计平滑来兜底，每一条都得在离线阶段验证到位。</p>\n<p>判断一个端侧 ASR 项目是否该走这条路，最终落在两个具体动作上：校准集能否覆盖部署分布的真实噪声与口音，以及异常值通道的高精度保留是否已进入实现预算。前者决定误差上界是否受控，后者决定 INT4 的带宽收益能否在不牺牲关键词识别的前提下兑现。两条都答不上来，低比特就只是把 FP16 的显存问题换成了准确率的运维问题。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-7\">七 · 量化在噪声段失效：一个端侧流式识别事故的解剖</h3>\n<p>某离线语音助手在实验室安静环境下验收通过，端侧实时率达标、功耗可控；部署到真实场景后，带背景噪声与口音的长语音出现句尾识别准确率明显下降。复盘发现根因不在声学模型本身，而在校准集：统计激活动态范围时只用了干净语音，噪声段的激活幅值远超校准得到的裁剪阈值，量化误差在噪声帧被放大，并沿解码器自回归链条逐步累积。这个事故划出了本节要讲的边界——低比特量化解决的是端侧 FP16 权重与激活占用大、显存带宽与矩阵乘算力受限、实时率与功耗难以满足离线语音助手需求的问题；它不解决分布外噪声与口音的鲁棒性，也不解决长语音下误差累积的稳定性，后者需要异常值保留、混合精度与 KV cache 误差补偿来兜底。</p>\n<p>量化本身按逐通道对称映射执行：<div class=\"formula\">$$q=\\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{x}{s}\\big),\\,-2^{b-1},\\,2^{b-1}-1\\Big),\\quad \\hat{x}=s\\cdot q,\\quad s=\\frac{\\max|x|}{2^{b-1}-1}$$</div>其中 $x$ 为权重或激活，$s$ 为逐通道缩放因子，$b$ 为比特数（INT8 取 8，INT4 取 4）。误差来源有两处：一是 $s$ 由校准集的最大幅值决定，校准分布偏窄时真实激活被 clip，误差不可逆；二是 INT4 下少数大幅值通道若不做异常值保留，矩阵乘结果整体偏移，表现为实时率提升但关键词识别失败率上升。工程上必须把“校准集覆盖真实噪声与口音”当作量化流程的一部分，而不是部署后的调优项。</p>\n<p>系统代价需要按边界分档评估。显存与带宽随比特数近似线性下降，这是收益侧；代价侧则是实现复杂度与稳定性风险：INT8 权重加在线激活量化在 Blackwell 边缘 SKU 上可走低比特 Tensor Core 或 DP4A 指令，收益确定、异常值处理简单；INT4 权重必须配异常值通道保留或混合精度，实现复杂度明显高于 INT8。解码器 KV cache 低比特存储降低自回归解码的显存读带宽，但若不做误差补偿，长语音按块滚动时误差逐步累积，句尾准确率显著低于句首——这正是事故中观察到的形态。因此适用边界是：离线语音助手等端侧低功耗、批大小为 1 或小批、以实时率与功耗为 SLO 的流式场景；上限受低比特量化误差与 KV cache 累积误差约束，长语音与分布外口音下准确率下降，此时应回退到 INT8 或对异常值通道保留高精度，而不是继续压比特数换实时率。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>量化收益</th><th>失效形态</th></tr></thead><tbody><tr><td>干净语音、短句</td><td>显存带宽线性下降，实时率达标</td><td>基本无</td></tr><tr><td>噪声段、口音</td><td>同上</td><td>激活动态范围偏窄，噪声帧误差放大</td></tr><tr><td>长语音自回归</td><td>KV cache 读带宽下降</td><td>误差沿解码链累积，句尾准确率下降</td></tr><tr><td>INT4 权重</td><td>算力与显存进一步压缩</td><td>异常值通道未保留，关键词识别失败率上升</td></tr></tbody></table>\n<h3 id=\"alg-asr-quant-edge-sec-8\">八 · 校准前向：把动态范围变成逐通道缩放因子</h3>\n<p>量化流水线的第一步不是量化，而是观测。校准集前向在 FP16 权重下跑一遍真实分布的帧块输入，逐层记录权重张量的逐输出通道最大值与激活张量的逐输入通道最大值，得到两组动态范围统计量。这一步的输入是校准语音集（覆盖噪声、口音、远场），输出是每层的缩放因子表 <span>s<sub>w</sub></span> 与 <span>s<sub>a</sub></span>，按通道存放，随权重一起固化进端侧模型包。代价落在离线侧：一次完整前向的算力开销与一次推理同级，但只做一次；端侧不承担任何校准成本，只承担读取缩放因子表的显存（每通道一个 FP16 标量，相对权重本身可忽略）。真正的工程风险在分布匹配：校准集若偏窄，激活动态范围估计偏小，端侧遇到噪声段时大幅值激活被裁剪，误差在噪声帧放大，识别准确率明显下降。因此校准集必须按真实噪声与口音分层采样，而不是拿干净朗读语料充数。</p>\n<div class=\"formula\">$$s=\\frac{\\max|W|}{2^{b-1}-1},\\quad q=\\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{x}{s}\\big),\\,-2^{b-1},\\,2^{b-1}-1\\Big),\\quad \\hat{x}=s\\cdot q$$</div>\n<p>逐通道而非逐张量是这里的核心选择：ASR 编码器的卷积与线性层通道间幅值差异大，逐张量缩放会让小幅值通道整体塌进零附近，逐通道缩放把每个输出通道独立归一，代价仅是缩放因子表的存储与反量化时的一次向量乘。INT4 时 <span>b=4</span>，分母变为 7，缩放因子的粒度必须更细，否则同一通道内的离群值会把其余权重压到只剩两三个可表示电平。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-9\">九 · 权重离线量化与异常值通道保留</h3>\n<p>权重侧在离线完成：按第一步的 <span>s<sub>w</sub></span> 把 FP16 权重映射为 INT8 或 INT4 整数，打包成端侧加载的紧凑布局。输入是 FP16 权重与缩放表，输出是低比特权重块加一份异常值掩码。异常值处理是本步骤的实质内容：统计每个通道的幅值分布，把显著偏离通道主体的少数通道标记出来，这些通道要么保留 FP16/INT8 高精度单独走一条小矩阵乘，要么在 INT4 下用更高的组内缩放精度单独编码。代价是双份实现复杂度——低比特主路径与高精度旁路要在同一个 kernel 内拼接结果，端侧代码体积与寄存器压力上升；收益是避免“实时率提升但关键词识别失败率上升”这一典型失败模式：少数大幅值通道量化后矩阵乘结果整体偏移，关键词 logits 被系统性压低。</p>\n<p>打包布局直接影响端侧显存带宽。INT4 权重按 32 个一组共享缩放因子（微缩放）时，每组附带一个 FP16 缩放，组越小精度越高、元数据开销越大；组越大元数据越省、组内离群值越难吸收。这个权衡在编码器与解码器上并不对称：编码器通道数大、组可以放粗；解码器权重矩阵窄，组必须收紧，否则自回归每一步的 logits 偏差会沿序列累积。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-10\">十 · 激活在线量化与低比特矩阵乘</h3>\n<p>推理时每个帧块进入编码器，激活在 kernel 内部在线量化：输入 FP16 激活块与预存的 <span>s<sub>a</sub></span>，输出 INT8 激活块，随即送入低比特矩阵乘。Blackwell 边缘 SKU 上这条路径走低比特 Tensor Core 或 DP4A 指令，前者适合规整的大矩阵乘（编码器前段卷积展开后的 GEMM），后者适合解码器里窄而碎的乘加。代价体现在两处：一是量化本身的逐元素 clip-round 开销，必须融进 load 阶段而不是单独一个 pass，否则带宽省下来的又被多一次读写吃掉；二是激活动态范围裁剪，端侧噪声段的瞬时大幅值激活超出校准范围时被截断，误差直接进入下一层。</p>\n<p>工程上的判断是：编码器激活量化用较宽的裁剪余量（宁可牺牲一点分辨率也不截断），解码器激活量化用较紧的范围（解码器输入分布稳定，收紧换分辨率更划算）。矩阵乘的输出是 INT32 累加，反量化回 FP16 后才进入下一层或残差相加，反量化的乘 <span>s<sub>w</sub>·s<sub>a</sub></span> 可以提前折叠进缩放表，避免每层重复计算。吞吐收益来自比特数近似线性的带宽下降：权重从 FP16 降到 INT8，读带宽减半，矩阵乘算力需求同步下降，端侧得以在同等功耗预算下跑更大模型或把实时率压到更低。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-11\">十一 · 解码器 KV cache 低比特存储与滚动</h3>\n<p>自回归解码阶段，KV cache 是显存读带宽的主要消费者。低比特存储的做法是把每层每头的 key/value 按通道或按头量化后写入 cache，读回时反量化参与注意力计算。输入是新 token 的 key/value 投影，输出是低比特 cache 条目加对应的缩放因子；每步解码要读全部历史 cache，因此这一步的代价是“写入一次、读取 T 次”的带宽结构，量化收益随序列长度放大。长语音必须按块滚动：只保留最近窗口的低比特 cache，窗口外的历史被丢弃或降精度摘要，以控制端侧显存上限。</p>\n<p>这里最需要警惕的是累积误差。低比特 KV cache 若不做误差补偿，每一步解码引入的微小偏差进入下一步的注意力输入，沿自回归链条逐步放大，表现为句尾识别准确率显著低于句首。可用的补偿手段包括：key 用比 value 更高的比特（key 参与 softmax 打分，对排序更敏感）；对 cache 做分组缩放而非全局缩放；在滚动窗口边界处保留一段高精度 cache 作为锚点。代价是显存节省比例被这些补偿吃掉一部分，工程上要在“省带宽”与“长语音准确率”之间按目标语音时长定档。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-12\">十二 · 反量化输出、流式拼接与端到端代价核算</h3>\n<p>解码器输出反量化后送语言模型或后处理，端侧按帧块流式识别：每个帧块走完“激活量化→低比特矩阵乘→反量化→解码→反量化输出”的完整链路，结果拼接成增量文本。输入是帧块与滚动 cache，输出是增量识别结果与更新后的 cache。这一步的代价是端到端延迟的构成：量化与反量化的逐元素开销、低比特矩阵乘的算力、cache 读带宽、以及帧块边界上的流水气泡。批大小通常为 1 或小批以控制延迟，因此吞吐不是端侧的主要指标，实时率与功耗才是。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>校准前向</td><td>分层校准语音集</td><td>逐通道缩放表</td><td>离线一次前向算力；分布不匹配则准确率劣化</td></tr><tr><td>权重离线量化</td><td>FP16 权重、缩放表</td><td>INT8/INT4 权重块、异常值掩码</td><td>高精度旁路的实现复杂度与寄存器压力</td></tr><tr><td>激活在线量化</td><td>FP16 激活块、<span>s<sub>a</sub></span></td><td>INT8 激活块</td><td>逐元素 clip-round；噪声段截断误差</td></tr><tr><td>低比特矩阵乘</td><td>低比特权重与激活</td><td>INT32 累加、反量化 FP16</td><td>算力与读带宽按比特数近似线性下降</td></tr><tr><td>KV cache 低比特</td><td>新 token 的 K/V 投影</td><td>低比特 cache、缩放因子</td><td>写一次读 T 次的带宽；长语音累积误差</td></tr><tr><td>反量化输出</td><td>解码器 logits</td><td>增量文本</td><td>帧块边界流水气泡；端到端实时率</td></tr></tbody></table>\n<p>把六步的代价叠起来看，端侧低比特 ASR 的预算分配有一个明确的优先级：KV cache 读带宽随语音时长增长，是长语音场景的第一约束；激活在线量化的截断误差决定噪声环境下的鲁棒性；权重异常值旁路决定关键词识别的下限。三者中任何一项失守，实时率的提升都会被准确率下降抵消。因此部署配方里，INT8 是默认档，INT4 只在异常值通道保留高精度且解码器 cache 采用混合比特时才启用——这不是精度偏好，而是端侧单流、批大小为 1 的负载形态下，误差没有批内平均可借，只能靠结构性的异常值保留与 cache 补偿来兜住。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-13\">十三 · 帧块流水上的量化边界：从校准到流式解码的失效链</h3>\n<p>端侧流式 ASR 的量化不是一次性离线动作，而是一条随帧块推进的流水线：校准集前向统计动态范围 → 逐通道缩放因子落定 → 权重离线 INT8/INT4 → 激活在线量化 → 低比特矩阵乘 → KV cache 低比特读写 → 反量化送后处理。每一步的输入输出与代价并不对称。校准步的输入是覆盖真实噪声与口音的语音片段，输出是每层权重与激活的逐通道缩放因子 $s$；代价是一次性离线算力，但它决定了后续所有步骤的误差基线。权重离线量化步输入 FP16 权重，输出整数张量与缩放因子表，代价是存储与一次性转换；推理时激活在线量化步输入每帧块的激活张量，输出量化整数，代价是逐帧的裁剪与缩放开销，且动态范围估计偏窄会直接把噪声段的量化误差放大。矩阵乘步用低比特 Tensor Core 或 DP4A 指令，代价从 FP16 的算力瓶颈转为指令吞吐与累加精度约束；KV cache 低比特存储步降低自回归解码的显存读带宽，代价是误差随解码步累积。整条流水上，显存与带宽按比特数近似线性下降，但每一步都引入了不可逆的信息损失，误差在长语音上沿时间轴叠加。</p>\n<p>量化本身的边界由逐通道对称公式刻画：</p>\n<div class=\"formula\">$$q=\\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{x}{s}\\big),\\,-2^{b-1},\\,2^{b-1}-1\\Big),\\quad \\hat{x}=s\\cdot q,\\quad s=\\frac{\\max|x|}{2^{b-1}-1}$$</div>\n<p>该式说明失效条件：当某通道存在少数远大于其余值的异常值时，$\\max|x|$ 被异常值主导，$s$ 被抬高，其余正常值被压进少数几个整数格点，量化误差在矩阵乘结果上表现为系统性偏移。INT4 下格点仅 16 个，这一效应远比 INT8 剧烈，因此 INT4 权重必须保留异常值通道的高精度或单独处理，否则实时率提升换来的是关键词识别失败率上升。激活侧的失效更隐蔽：校准集未覆盖真实噪声与口音时，激活动态范围估计偏窄，端侧部署后噪声段的激活超出校准区间被 clip，误差在噪声段集中放大，识别准确率明显下降。这是一条从校准分布到部署分布的失配链，而非单点数值问题。</p>\n<p>系统代价需按步拆开看，不能只看比特数带来的线性收益：</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入→输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>校准统计</td><td>语音片段→逐通道 $s$</td><td>一次性离线算力</td><td>噪声/口音未覆盖，动态范围偏窄</td></tr><tr><td>权重离线量化</td><td>FP16 权重→INT8/INT4</td><td>转换与缩放表存储</td><td>INT4 未保留异常值通道</td></tr><tr><td>激活在线量化</td><td>帧块激活→整数</td><td>逐帧裁剪开销</td><td>激活异常值导致误差累积</td></tr><tr><td>低比特矩阵乘</td><td>整数张量→累加结果</td><td>指令吞吐与累加精度</td><td>混合精度实现复杂度上升</td></tr><tr><td>KV cache 低比特</td><td>历史键值→低比特存储</td><td>解码读带宽下降</td><td>长语音自回归误差累积</td></tr></tbody></table>\n<p>表中最后一行是端侧流式识别最容易被低估的代价：解码器 KV cache 低比特存储减少了自回归解码的显存读带宽，但未做误差补偿时，误差随解码步逐步累积，句尾识别准确率显著低于句首——这与按帧块滚动控制显存的策略叠加，形成“越长的语音越不准”的退化曲线。工程判断因此落在两处：一是异常值通道的保留策略必须在 INT4 下默认开启，混合精度实现复杂度是必要代价而非可选优化；二是 KV cache 的低比特位宽应与语音块长度绑定，长语音场景下宁可对 KV 保留更高位宽或做周期性高精度重算，也不要把位宽压到误差累积不可控的水平。校准集覆盖真实噪声与口音、激活在线量化的动态范围裁剪，这两项稳定性技巧的收益不在峰值实时率，而在把失配链的起点堵住。</p>\n<h3 id=\"alg-asr-quant-edge-sec-14\">十四 · 逐通道缩放的推导起点</h3>\n<p>端侧 ASR 的量化误差不是均匀分布的：同一层内不同输出通道的权重幅值差异可达一个数量级以上，而激活的幅值又随帧块内容剧烈波动。若整层共用一个缩放因子，缩放因子会被最大幅值通道绑架，小幅值通道的有效位数被压缩到几乎为零。逐通道量化的关键一步，是把“一个张量一个尺度”拆成“一个通道一个尺度”，让每个通道用自己的动态范围决定舍入网格。</p>\n<p>推导从对称量化的舍入误差上界开始。设某通道权重向量为 <span class=\"inline-math\">W</span>，缩放因子 <span class=\"inline-math\">s</span>，量化整数 <span class=\"inline-math\">q = round(W/s)</span>，则单元素误差满足 <span class=\"inline-math\">|W - s·q| ≤ s/2</span>。要让这个上界最小，直觉是让 <span class=\"inline-math\">s</span> 尽量小；但 <span class=\"inline-math\">s</span> 太小会使 <span class=\"inline-math\">max|W|/s</span> 超出 <span class=\"inline-math\">2^{b-1}-1</span> 的表示范围而发生截断，截断误差远大于舍入误差。于是约束变为：在“不截断”的前提下取最小的 <span class=\"inline-math\">s</span>，即</p>\n<div class=\"formula\">$$s = \\frac{\\max|W|}{2^{b-1}-1}$$</div>\n<p>这一步就是逐通道缩放的全部推导核心：分母是 b 比特有符号整数的正半轴容量，分子是该通道的绝对最大值。代入 INT8 时 <span class=\"inline-math\">b=8</span>，分母为 127；INT4 时 <span class=\"inline-math\">b=4</span>，分母为 7。分母从 127 掉到 7，意味着同样的权重幅值被映射到只有 15 个格点的网格上，舍入误差上界放大约 18 倍——这就是 INT4 必须引入异常值保留的根本原因，而不是实现偏好问题。</p>\n<p>把逐通道误差聚合到矩阵乘输出，可以看清系统代价落在哪里。对输出通道 <span class=\"inline-math\">j</span>，其点积误差近似为 <span class=\"inline-math\">Σ_i |x_i| · s_j/2</span>，即误差与输入激活的绝对值之和成正比、与该输出通道的缩放因子成正比。激活幅值大的帧块（噪声段、爆破音）会把这个误差放大，这正是失败模式中“噪声段量化误差放大”的解析来源。工程含义是：权重量化的缩放因子可以离线一次算定，但激活量化的缩放因子必须按帧块在线估计，否则噪声段的激活动态范围会被静音段拉窄。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-15\">十五 · 激活在线量化的伪代码与代价</h3>\n<p>激活量化不能照搬权重的离线流程，因为激活的 <span class=\"inline-math\">max|x|</span> 在推理时才出现。端侧可行的做法是逐帧块（per-token 或 per-frame-block）统计绝对值最大值，得到一个标量或逐通道向量缩放因子，再走同一套 clip-round 公式。伪代码思路如下：</p>\n<ul>\n<li>输入帧块激活 <span class=\"inline-math\">X</span>（形状为帧块长度 × 通道数），先求 <span class=\"inline-math\">a = max|X|</span>（逐通道则沿帧块维求最大值向量）。</li>\n<li>计算 <span class=\"inline-math\">s_a = a / (2^{b-1}-1)</span>，对 <span class=\"inline-math\">s_a</span> 做下限保护，避免全零帧块除零。</li>\n<li>量化 <span class=\"inline-math\">q = clip(round(X / s_a), -2^{b-1}, 2^{b-1}-1)</span>，随后以 INT8/INT4 送入 Tensor Core 或 DP4A 做整数矩阵乘。</li>\n<li>矩阵乘累加结果为整数，乘以 <span class=\"inline-math\">s_a · s_w</span> 完成反量化，再进入下一层。</li>\n<li>若某通道 <span class=\"inline-math\">a</span> 超过预设阈值，将该通道标记为异常值通道，走 FP16 旁路而不是强行量化。</li>\n</ul>\n<p>这条路径的代价首先体现在延迟上：每层多出一次归约求最大值和一次逐元素缩放，属于访存受限操作，在端侧单流、批大小为 1 的形态下无法被批处理摊薄，直接计入每帧块的关键路径。其次是精度代价：per-token 缩放只用一个标量，通道间幅值差异被抹平，异常值通道会把整个帧块的缩放因子抬高，压低其余通道的有效位数。第三是带宽代价的收益侧：激活从 FP16 降到 INT8，矩阵乘的输入读带宽近似减半，这是端侧实时率提升的主要来源；但反量化与旁路分支带来额外的寄存器压力和控制流开销，在小模型上这部分开销占比不可忽略。</p>\n<p>具体例子：一个编码器层接收 40 维滤波器组特征扩展后的帧块，某帧块因突发噪声使某通道激活幅值达到静音段的数十倍。若用整层单一缩放因子，静音段通道的量化格点几乎退化为零；改用逐通道缩放后，噪声通道单独承担大缩放因子，其余通道恢复正常分辨率，代价是该通道的整数乘法结果需要更宽的累加位宽来容纳。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-16\">十六 · 异常值保留的判定与混合精度分支</h3>\n<p>异常值保留不是“把大数挑出来”这么简单，它需要在离线阶段就确定哪些通道走旁路，否则推理时的分支判定会引入数据依赖的控制流，破坏流水。判定依据可以直接从缩放因子推导：若某通道的 <span class=\"inline-math\">max|W|</span> 显著高于同层中位数，则该通道量化后的相对误差 <span class=\"inline-math\">s/(2·max|W|)</span> 虽然不变，但其对点积的绝对贡献 <span class=\"inline-math\">Σ|x_i|·s/2</span> 却因 <span class=\"inline-math\">s</span> 大而成比例放大。因此保留判据应基于“误差贡献”而非“幅值大小”：</p>\n<div class=\"formula\">$$\\text{keep}_j = \\mathbb{1}\\Big[\\frac{\\max|W_j|}{\\mathrm{median}_k \\max|W_k|} &gt; \\tau\\Big]$$</div>\n<p>阈值 <span class=\"inline-math\">τ</span> 由校准集上的端到端识别损失反推，而不是拍脑袋定。被标记的通道在离线量化时保持 FP16，推理时与低比特主路径并行计算后相加。这一步的工程代价是显存：旁路通道的权重不参与比特数线性下降，若旁路比例高，显存收益被侵蚀；同时混合精度分支使矩阵乘无法用单一指令完成，需要拆成整数主乘加与 FP16 补乘两段，端侧单流下两段之间的同步开销直接体现为延迟。</p>\n<p>具体例子：解码器某注意力输出投影层中，少数通道承载了位置编码相关的大幅值成分，INT4 量化后这些通道的舍入使注意力分数偏移，表现为关键词识别失败率上升而整体字错率变化不明显。把这几条通道切到 FP16 旁路后，主路径仍是 INT4，显存收益保留大部分，而关键词召回恢复。这说明异常值保留的收益是“保关键能力”，不是“降平均误差”。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-17\">十七 · KV cache 低比特存储的误差累积推导</h3>\n<p>自回归解码的 KV cache 是端侧长语音场景的显存主项。把 K/V 按同一套对称量化公式压到 INT8/INT4，读带宽近似按比特数下降，但误差会随解码步数累积。推导关键一步是把单步误差写成递推：设第 <span class=\"inline-math\">t</span> 步注意力输出误差为 <span class=\"inline-math\">ε_t</span>，其来源是历史 K/V 的量化误差经 softmax 加权后的线性组合，而 <span class=\"inline-math\">ε_t</span> 又通过残差流进入第 <span class=\"inline-math\">t+1</span> 步的查询，形成</p>\n<div class=\"formula\">$$\\varepsilon_{t+1} \\approx \\varepsilon_t + \\sum_{i\\le t} \\alpha_{t,i}\\,\\delta_i$$</div>\n<p>其中 <span class=\"inline-math\">δ_i</span> 是第 <span class=\"inline-math\">i</span> 个历史位置的 K/V 量化误差，<span class=\"inline-math\">α_{t,i}</span> 是 softmax 权重。由于 <span class=\"inline-math\">α</span> 之和为 1，误差不会指数爆炸，但会随 <span class=\"inline-math\">t</span> 单调累积——这解释了为什么句尾识别准确率显著低于句首，而不是整体均匀劣化。工程上可做的补偿是：对近期窗口用高精度 K/V，对远端历史用低比特，即按块滚动的混合精度 cache；或对 K 保留 INT8、对 V 用 INT4，因为 V 的误差经加权求和后被平滑，而 K 的误差直接改变 softmax 分布。</p>\n<p>代价方面，KV cache 低比特化降低的是解码阶段的读带宽，而解码阶段在端侧流式识别中恰是逐帧串行、无法批处理的部分，因此带宽收益直接转化为每帧解码延迟的下降。但混合精度窗口意味着 cache 管理逻辑变复杂：滚动时要决定哪些块升级、哪些块降级，升级操作本身是一次读+写，若滚动粒度过细，管理开销会吃掉带宽收益。</p>\n<p>具体例子：一段长语音在解码到后半段时，远端历史的 V 被压到 INT4，softmax 权重很小的位置误差被平滑掉；但 K 的 INT4 误差改变了注意力分布的尖锐程度，使解码器对同音词的区分能力下降。把 K 固定在 INT8、仅 V 走 INT4，可在保留大部分带宽收益的同时抑制这一劣化。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-18\">十八 · 校准与前向统计的可实现流程</h3>\n<p>校准集的作用是估计每层权重与激活的动态范围，其覆盖度直接决定缩放因子是否可信。可实现流程是：取一批真实噪声与多口音的短语音片段，按端侧相同的帧块切分与前处理走一遍前向，逐层记录权重绝对值最大值与激活的逐通道最大值分布；对激活取高分位数而非绝对最大值，以避免单个极端帧块把缩放因子抬高。这里的关键判断是：权重用绝对最大值（离线一次定死，无截断风险），激活用分位数（在线逐帧块重估，允许少量截断换取分辨率）。</p>\n<p>伪代码层面，校准与推理共享同一套量化函数，区别只在缩放因子的来源：校准阶段把统计量写入每层的缩放因子表，推理阶段权重直接查表，激活现场计算。这样实现的好处是量化路径只有一份代码，校准与部署的数值行为一致，避免“校准用一套、推理用另一套”导致的分布外劣化。代价是校准阶段需要保存逐通道统计量，对层数多的模型是一笔一次性显存开销，但可离线完成后丢弃。</p>\n<p>失败模式的解析在这里落地：校准集未覆盖真实噪声与口音时，激活动态范围估计偏窄，缩放因子偏小，部署后噪声段的激活大量触发 clip，截断误差取代舍入误差成为主项，识别准确率明显下降。这不是量化公式的问题，而是 <span class=\"inline-math\">max|x|</span> 估计的分布失配问题。工程判断是：校准集的噪声类型与口音覆盖应作为量化方案的一部分被显式管理，其重要性不低于比特数选择。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-19\">十九 · 比特数、指令与实时率的联合取舍</h3>\n<p>把公式里的 <span class=\"inline-math\">b</span> 当作唯一旋钮是错的。端侧实时率由三部分构成：整数矩阵乘的算力、激活与权重的读带宽、以及量化/反量化的访存开销。从 FP16 到 INT8，权重与激活带宽近似减半，矩阵乘吞吐在支持 DP4A 或低比特 Tensor Core 的边缘 SKU 上提升，反量化开销相对可控；从 INT8 到 INT4，带宽再减半，但异常值旁路比例上升、累加位宽与混合精度分支的开销占比上升，净收益取决于旁路比例与层形状。</p>\n<p>可操作的取舍判据是把每层的“收益/开销比”写出来：收益正比于该层权重与激活的字节数下降，开销正比于旁路通道比例与反量化元素数。对通道数大、旁路比例低的层（如编码器前段的大矩阵乘），INT4 收益明确；对通道数小、旁路比例高的层（如解码器输出投影），INT8 甚至 FP16 旁路更划算。这与“全模型统一比特数”的直觉相反，但在端侧单流、批大小为 1 的形态下，逐层选择比特数比全局统一更能守住实时率。</p>\n<p>具体例子：编码器主体走 INT4 权重加 INT8 激活，解码器注意力输出投影保留 INT8 并对少数通道走 FP16 旁路，KV cache 的 V 走 INT4、K 走 INT8。这套组合的显存与带宽收益主要来自编码器主体与 V cache，而精度敏感点被单独保护。最终落在工程判断上：量化的比特数分配应按层的误差贡献与旁路成本逐层决定，公式只提供单层的误差上界，系统收益要在层间重新分配。</p>\n<h3 id=\"alg-asr-quant-edge-sec-20\">二十 · 请求形态决定量化收益的形状</h3>\n<p>低比特量化在端侧 ASR 上的收益不是一条平直的曲线，它随请求形态变化而折叠。端侧流式语音识别的请求形态是“按帧块输入”：音频以固定帧块（典型为数十毫秒级）持续喂入编码器，编码器输出接解码器自回归出词，整条链路是单流、长驻、低并发的。这种形态对量化的敏感点与离线整段转写完全不同——离线整段转写可以把整段音频一次性铺满批维度，用大矩阵乘摊薄权重读取；流式帧块则要求每个帧块到达后尽快吐出结果，矩阵乘的 M 维（帧块长度）很小，权重读取带宽成为主导项，而不是算力。于是 INT8/INT4 权重量化在这里的直接收益是“每帧块少读多少权重字节”，而非“每帧块少做多少次乘加”。</p>\n<p>把这一判断写成可核算的量：设某层权重元素数为 $N$、位宽为 $b$，则该层每帧块前向的权重读取字节约为 $N\\cdot b/8$（忽略激活与中间结果）。从 FP16（$b=16$）降到 INT8（$b=8$）意味着该层权重读取量减半，降到 INT4（$b=4$）再减半。对帧块长度很小的流式请求，这个减半几乎线性映射到每帧块延迟的下降；而对批大小被拉大的离线请求，权重读取被批内多帧共享摊薄，同样的位宽下降带来的延迟收益就被稀释。这就是负载配方要回答的第一个问题：请求形态是否让权重读取处在关键路径上。端侧单流流式识别正是让权重读取处在关键路径上的形态，所以低比特量化的收益最“实”。</p>\n<p>与之相对，长度分布是第二个变量。短请求（单句、数秒音频）的解码步数少，KV cache 尚未长到主导显存读带宽，量化收益主要落在编码器权重上；长请求（长语音、连续口述）的解码步数多，KV cache 的低比特存储成为显存读带宽的主要贡献项，此时若 KV cache 仍为 FP16，权重侧再省也压不住解码阶段的带宽压力。因此负载配方必须把“长度分布”与“量化落点”对齐：短请求优先压权重，长请求必须同时压 KV cache。这一点在机制上对应“解码器 KV cache 同样低比特存储以减少自回归解码显存读带宽”，但它的收益兑现依赖于长度分布落在长尾。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-21\">二十一 · 批大小与并发：小批是延迟约束下的必然，也是量化误差的放大器</h3>\n<p>端侧流式识别的批大小通常为 1 或小批，这不是调度偏好，而是 SLO 约束下的必然：流式交互要求首帧块结果尽快返回，批内等待会直接推高首字延迟。小批带来的系统后果是矩阵乘的算术强度低——每读一次权重只做很少的乘加，硬件处于带宽受限而非算力受限区间。低比特量化恰好作用于这个区间，所以小批形态下量化的延迟收益最明显；反过来，如果把端侧模型搬到有并发聚合的服务器侧做大批，量化带来的边际延迟收益会迅速衰减，因为权重读取已被摊薄，瓶颈转移到算力或 KV cache 带宽。</p>\n<p>但小批同时是量化误差的放大器。批大小为 1 时，每一帧块的激活分布都独立进入在线量化，没有批内统计平滑；一旦某帧块落入噪声段或口音偏移段，激活动态范围估计偏窄，量化步长 $s$ 被压小，clip 截断与 round 误差同时放大。用公式看：$\\hat{x}=s\\cdot\\mathrm{clip}(\\mathrm{round}(x/s),-2^{b-1},2^{b-1}-1)$，当 $s$ 由偏窄的动态范围估出时，超出范围的大幅值被硬截断，误差不再是有界均匀噪声而是系统性偏移。小批下这种偏移没有任何跨样本平均来抵消，直接进入解码器，表现为该帧块对应词的识别错误。这就是“校准集未覆盖真实噪声与口音、激活动态范围估计偏窄、端侧部署后量化误差在噪声段放大”的失败模式在小批形态下的具体发生路径。</p>\n<p>并发维度上，端侧是单流，服务器侧才有多流并发。负载配方要区分这两种并发语义：端侧单流的并发是“时间上的连续帧块”，量化误差沿时间轴累积；服务器多流的并发是“空间上的批聚合”，量化误差被批内平均但吞吐收益被摊薄。把端侧单流配方直接套到服务器多流，会得到“实时率提升但准确率劣化”的错配——因为校准集与真实分布不匹配时，量化在噪声段放大误差，而多流聚合并不会修复这个分布偏移，只是把它平均进更多请求里。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-22\">二十二 · 长度分布与 KV cache 滚动：长语音是配方失效的第一现场</h3>\n<p>端侧流式识别对长语音的处理是按块滚动 KV cache：解码器只保留最近窗口的 KV，超出窗口的历史被丢弃或压缩。这个机制本身是为控制显存而设，但它与低比特 KV cache 叠加时会产生一个配方层面的耦合问题——滚动窗口的边界处，被丢弃的历史所携带的上下文信息本就稀薄，低比特存储再引入量化误差，边界处的解码条件进一步劣化。长语音的自回归解码误差逐步累积，表现为句尾识别准确率显著低于句首，这正是“低比特解码 KV cache 未做误差补偿、长语音自回归解码误差逐步累积”的失败模式。</p>\n<p>把累积误差写成可追踪的量：设解码步 $t$ 的 KV 量化误差为 $\\epsilon_t$，自回归解码把上一步的输出作为下一步的输入条件，误差沿链传导并可能被放大，$t$ 步后的条件偏差近似为 $\\sum_{i\\le t} \\alpha^{t-i}\\epsilon_i$（$\\alpha$ 为传导增益，定性描述其存在而不给定数值）。滚动窗口把 $t$ 截断在窗口长度内，限制了累积步数，但也意味着窗口外的历史无法通过更长上下文来纠偏。于是长度分布与窗口长度的匹配成为配方关键：窗口过短，长语音的跨句指代与实体一致性丢失；窗口过长，低比特 KV 的误差累积步数增加。负载配方要给出的不是某个固定窗口值，而是“窗口长度随长度分布的分位数走”的工程判断——以请求长度分布的高分位为窗口下界，避免大多数长请求落在窗口外。</p>\n<p>显存代价上，KV cache 低比特存储的收益按位宽近似线性：FP16 到 INT8 使 KV 读带宽减半，INT8 到 INT4 再减半。但长语音下 KV cache 的容量本身随长度线性增长，位宽减半只是把增长斜率减半，不改变“长语音必然吃满显存”的趋势。因此长语音配方的正确做法是位宽压缩与滚动窗口两条腿同时走，只做其中一条都会在长度分布的长尾处失效。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-23\">二十三 · 异常值通道与 INT4：配方在比特数上的分档判断</h3>\n<p>INT8 与 INT4 在负载配方上不是同一个档位。INT8 权重量化在端侧流式识别上通常可以全通道统一处理，逐通道缩放因子由校准集统计得到，激活在线量化的动态范围裁剪也相对宽容；INT4 则必须保留异常值通道，因为少数大幅值通道量化后矩阵乘结果偏移，会直接表现为关键词识别失败率上升——这正是“INT4 权重未保留异常值通道、少数大幅值通道量化后矩阵乘结果偏移、实时率提升但关键词识别失败率上升”的失败模式。异常值通道保留高精度或单独处理，意味着实现上要维护混合精度的矩阵乘路径，复杂度高于 INT8，这是配方在比特数分档时必须计入的工程成本。</p>\n<p>用公式定位异常值的影响：逐通道缩放 $s_c=\\max|W_c|/(2^{b-1}-1)$ 由该通道最大幅值决定。若某通道存在远大于其余元素的异常值，$s_c$ 被这个异常值抬高，通道内其余元素的量化步长随之变大，小幅值元素的相对误差被放大；反过来若不抬高 $s_c$，异常值本身被 clip 截断，产生系统性偏移。两种处理都指向同一结论：异常值通道不能与普通通道共用一套缩放策略，必须单独保留高精度。INT4 下 $2^{b-1}-1=7$，量化格点极稀疏，异常值的影响被进一步放大，所以 INT4 配方必须把异常值通道识别作为前置步骤，而不是可选项。</p>\n<p>系统代价上，异常值通道保留高精度会局部破坏“位宽线性降带宽”的假设：被保留的通道仍按 FP16 读取，整体带宽下降幅度小于名义位宽比。负载配方要据此调整预期——INT4 的实际带宽收益是“INT4 通道占比 × 1/4 + 保留通道占比 × 1”的加权，而非简单的 1/4。这个加权系数取决于模型权重分布，需在校准阶段统计，不能凭比特数直接外推。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-24\">二十四 · 校准集与真实分布的错配：配方失效的根因</h3>\n<p>负载配方里最容易被忽略的一项是校准集与端侧真实分布的匹配度。校准集前向统计各层权重与激活的动态范围，确定逐通道缩放因子；如果校准集未覆盖真实噪声与口音，激活动态范围估计偏窄，端侧部署后量化误差在噪声段放大。这个失效不是渐进的，而是断崖式的：安静段校准出的动态范围在噪声段被大幅值激活突破，clip 截断集中发生在噪声帧块，识别准确率在噪声段明显下降，而安静段几乎不受影响。负载配方因此要把“部署环境的噪声与口音分布”作为校准集设计的输入，而不是拿通用语料校准后直接下发。</p>\n<p>错配的另一个方向是长度分布错配：用短句校准集统计出的 KV cache 动态范围，在长语音上不成立，因为长语音的 KV 幅值分布随上下文增长而漂移。校准集若只覆盖短请求，长语音的 KV 量化误差补偿就无从设计，长语音句尾准确率下降的失败模式便不可避免。配方层面的对策是把校准集按请求形态与长度分布分层采样，每层单独统计动态范围，而不是全局一套缩放因子。</p>\n<p>从系统代价看，校准集错配的代价不是延迟或吞吐，而是准确率这一不可交易的 SLO。端侧语音助手的 SLO 以实时率与功耗衡量，但准确率是硬门槛：实时率提升而准确率劣化的配方在工程上不可接受。因此负载配方的判断顺序应是先锁定准确率边界（校准集覆盖度、异常值处理、KV 误差补偿），再在边界内优化实时率与功耗，而不是反过来先压位宽再看准确率掉多少。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-25\">二十五 · 配方的工程判断：形态、长度、批、位宽四者对齐</h3>\n<p>把上述几条收束成一个可执行的判断链：先看请求形态是否让权重读取处在关键路径上——端侧单流流式帧块输入满足这一条，低比特权重量化的延迟收益最实；再看长度分布的分位数——长尾请求决定 KV cache 位宽与滚动窗口必须同时压缩；再看批大小——小批是延迟约束下的必然，也是量化误差的放大器，配方要接受小批并为此加固校准与异常值处理；最后看位宽分档——INT8 可全通道统一，INT4 必须保留异常值通道并计入混合精度实现的复杂度。四者不对齐时，典型后果是“实时率提升但准确率劣化”，而这一后果在端侧是不可接受的。</p>\n<p>一个具体的对齐例子：某端侧语音助手以连续口述为主要请求形态，长度分布长尾明显，批大小为 1。配方应取编码器权重 INT8、解码器 KV cache INT8 并配滚动窗口，窗口下界取长度分布高分位；INT4 只在权重异常值通道已被识别并保留高精度的前提下用于编码器，且需核算实际带宽收益的加权系数而非名义 1/4。若把该配方换成短句校准集加 INT4 全通道统一，则噪声段与长语音句尾两处失败模式会同时触发，实时率账面提升被准确率劣化抵消。</p>\n<p>最终落在机制上：负载配方的本质是把量化位宽、KV cache 策略、批大小与校准集覆盖度这四个旋钮，按请求形态与长度分布拧到同一组取值上；任何一只旋钮单独拧过头，都会在端侧单流小批的形态下被误差放大机制捕捉到，表现为特定帧块或特定句尾的识别失败。工程判断的依据不是比特数本身，而是“该比特数下权重读取是否仍在关键路径、异常值通道是否已被隔离、KV 误差是否已被窗口截断”。</p>\n<h3 id=\"alg-asr-quant-edge-sec-26\">二十六 · 硬件档位与指令路径的选择</h3>\n<p>端侧 ASR 的部署配方第一步不是选模型，而是选指令路径。Blackwell 边缘 SKU 上可用的低比特矩阵乘路径有两条：低比特 Tensor Core 与 DP4A。二者的取舍不取决于峰值算力，而取决于本层矩阵的形状与权重比特数。编码器前几层是宽卷积或大隐层 GEMM，K 维足够长，INT8 走 Tensor Core 能摊薄指令开销；解码器自回归步的 GEMM 是 M=1 的瘦矩阵，Tensor Core 的利用率被 tile 填充吃掉，此时 DP4A 的逐 4 字节点积累加反而更省。工程判断是：编码器按层标注走 Tensor Core，解码器步进路径固定走 DP4A，中间不做运行时探测——端侧没有余量做 autotune。</p>\n<p>档位划分按功耗包络而非算力包络。同一颗边缘 SKU 在不同功耗封顶下可持续的频率不同，低比特路径的收益必须放在“每瓦实时率”上衡量，而不是 TOPS。设单帧块计算量为 $C$ 次乘加，目标实时率为 $R$（识别 1 秒音频所需墙钟秒数），则功耗约束可写成：</p>\n<div class=\"formula\">$$\\frac{C\\cdot R}{\\eta_{\\text{bit}}\\cdot P_{\\text{cap}}} \\le \\text{budget},\\qquad \\eta_{\\text{bit}}=\\frac{b_{\\text{fp16}}}{b_{\\text{int}}}$$</div>\n<p>其中 $\\eta_{\\text{bit}}$ 是比特数带来的理论带宽与算力缩减比，INT8 取 2、INT4 取 4，但实际有效值要乘一个指令利用率折扣。这个式子的用处是：当功耗封顶下调时，唯一还能保住实时率的杠杆是降低 $b_{\\text{int}}$ 或减少 $C$，而不是提高频率。举例：一个编码器隐层 1024、帧块 40 帧的配置，FP16 下实时率贴着 1.0 边缘，切到 INT8 权重加在线 INT8 激活后，带宽项按 2 倍缩减，实时率留出余量；若继续压到 INT4 权重，必须同时确认异常值通道已保留，否则省下的功耗会被准确率回退抵消。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-27\">二十七 · 并行拓扑：编码器与解码器的流水切分</h3>\n<p>端侧单流场景下，“并行”不是数据并行，而是编码器与解码器之间的流水重叠。流式识别按帧块推进，编码器对第 $k$ 块做前向的同时，解码器还在对第 $k-1$ 块的输出做自回归展开。拓扑上把两者放在同一设备的不同执行流，用一块双缓冲的隐层输出做交接：编码器写 buffer A 时解码器读 buffer B，反之亦然。这样做的代价是显存里常驻两份块级隐层，收益是解码器的 KV 读带宽与编码器的矩阵乘算力不再串行叠加。</p>\n<p>流水深度的选择有明确约束。设编码器单块耗时 $T_e$、解码器单块耗时 $T_d$，若 $T_d &gt; T_e$，流水无法隐藏解码，瓶颈在解码器，此时应优先压解码器的 KV 读带宽而不是继续优化编码器。反之若 $T_e$ 占优，则编码器的低比特 GEMM 是主战场。端侧实测这两个量的办法很朴素：在目标 SKU 上分别跑纯编码与纯解码的帧块循环，取稳态每块墙钟。配方里把这两个数写进配置注释，后续任何量化方案变更都要重测，因为 INT4 权重对两者的缩减比例不同——解码器瘦 GEMM 对权重比特更敏感，编码器大 GEMM 对激活比特更敏感。</p>\n<p>不要在这一层引入跨设备并行。端侧没有 NVLink 5 的带宽余量，NCCL 集合通信的固定开销会直接吃掉帧块预算；分离式预填/解码那套拓扑属于数据中心侧，边缘配方里编码器与解码器必须同设备。唯一例外是双芯片封装的高端边缘件，此时可按层切分而非按阶段切分，把编码器后半段与解码器整体放到第二芯片，交接只传块级隐层，通信量按帧块大小线性增长而非按模型深度增长。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-28\">二十八 · 量化方案的组合与异常值处理</h3>\n<p>权重离线量化用逐通道对称方案，缩放因子按输出通道统计：</p>\n<div class=\"formula\">$$s_c=\\frac{\\max_{i}|W_{c,i}|}{2^{b-1}-1},\\qquad \\hat{W}_{c,i}=s_c\\cdot \\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{W_{c,i}}{s_c}\\big),-2^{b-1},2^{b-1}-1\\Big)$$</div>\n<p>逐通道而非逐张量的理由是 ASR 编码器的卷积核与 GEMM 权重在通道间动态范围差异大，逐张量缩放会让小通道整体塌到零。INT8 下逐通道足够；INT4 下必须叠加异常值通道保留：统计每个通道的幅值分布，把超过某分位数的通道单独列出，这些通道的权重保持 INT8 或 FP16，其余走 INT4。异常值通道的数量直接决定混合精度矩阵乘的实现复杂度——若异常值通道在 K 维上不连续，低比特 Tensor Core 的 tile 会被打断，实际收益低于比特数比例。</p>\n<p>激活在线量化的难点是动态范围随输入分布漂移。噪声段与安静段的激活幅值差一个量级以上，固定缩放因子会在噪声段削顶。配方采用按帧块统计的滑动窗口：每个块前向时先算该块激活的最大幅值，与历史窗口的指数滑动值取大者作为缩放因子，再对该块做量化。这多了一次归约的开销，但避免了校准集偏窄导致的削顶。校准集本身要覆盖真实噪声与口音，这是失败模式里最常踩的一条：校准集干净、部署环境嘈杂时，实时率提升而准确率在噪声段明显下降。</p>\n<p>KV cache 的低比特存储是独立决策，不与权重量化捆绑。解码器 KV 按头维度逐通道量化到 INT8 是安全的基线；压到 INT4 必须做误差补偿，否则长语音的自回归误差逐步累积，句尾准确率显著低于句首。补偿的工程做法是在每块解码结束后用高精度重算一次注意力输出的均值偏移，把偏移量加回下一块的 KV 反量化结果，代价是每块一次额外归约，显存带宽开销小于把 KV 整体升回 INT8。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-29\">二十九 · KV 策略：滚动窗口与块级淘汰</h3>\n<p>端侧长语音的 KV 不能无限增长。配方用固定容量的环形缓冲：容量按目标最长语音与帧块数算出，写满后最老的块被淘汰。淘汰不是简单丢弃，而是把被淘汰块的 KV 做一次低比特摘要——按头求均值后以 INT8 存一个压缩槽，注意力计算时把压缩槽作为一个额外的“远历史”键参与打分。这样显存占用是常数，远历史的精度损失可控。代价是每块注意力多一次对压缩槽的读取，读带宽按压缩槽大小而非原始 KV 大小计。</p>\n<p>容量与精度的权衡可写成：设原始 KV 每块占 $M$ 字节，压缩槽占 $M/\\rho$ 字节，窗口保留 $n$ 块，则常驻显存为 $nM + M/\\rho$。$\\rho$ 取 4 时压缩槽开销可忽略，但远历史的分辨率下降；$\\rho$ 取 2 时精度好但常驻显存翻倍。端侧配方通常取 $\\rho=4$ 并把窗口长度设到覆盖一个完整语句的时长，因为跨语句的远历史对识别准确率的贡献远小于句内上下文。这个判断要在目标语种上验证：黏着语的长词跨块边界多，窗口需要更长。</p>\n<p>KV 低比特与滚动窗口叠加时有一个陷阱：淘汰块的摘要若用低比特 KV 反量化后再求均值，误差会被二次放大。正确顺序是先在高精度域求均值再量化摘要，即摘要路径绕开低比特 KV 的反量化。实现上这意味着解码器要保留一份块级高精度注意力输出的旁路，只在块结束时用一次，显存开销是一块的量级，可接受。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-30\">三十 · 调度参数与可复现配置思路</h3>\n<p>端侧调度的参数集很小，但每个都要写死而不是自适应。帧块大小决定延迟下限与流水重叠度：块太小则每块的固定开销占比高，块太大则首字延迟不可接受。配方把块大小设为编码器感受野的整数倍，使块边界不切断音素。批大小固定为 1，不引入连续批处理——端侧单流场景下批处理的收益被延迟惩罚抵消，连续批处理那套调度属于服务端条目，此处只用一句话指路。解码步数上限按块内最大音素数设，超限则强制输出并进入下一块，防止单块卡死拖垮实时率。</p>\n<p>可复现的配置思路按以下顺序落地，每步都有可验证的观测量：</p>\n<ul>\n<li>先在目标 SKU 上测 FP16 基线的每块编码耗时与解码耗时，确定瓶颈在 $T_e$ 还是 $T_d$。</li>\n<li>权重离线量化到 INT8 逐通道，异常值通道按分位数统计后单独标注；跑校准集与真实噪声集，比对噪声段的削顶比例。</li>\n<li>激活在线量化加滑动窗口缩放，观测每块激活最大幅值的分布，确认窗口长度覆盖噪声段的突发。</li>\n<li>KV 压到 INT8 逐头，长语音跑句尾准确率；若句尾回退明显，加块级均值偏移补偿。</li>\n<li>若功耗封顶仍紧，权重降 INT4 并保留异常值通道，重测 $T_e$ 与 $T_d$——两者缩减比例不同，流水深度可能要重调。</li>\n<li>最后固定帧块大小与解码步数上限，把上述所有参数连同测得的 $T_e$、$T_d$ 写进配置文件，任何量化方案变更都触发重测。</li>\n</ul>\n<p>这套顺序的关键在于每一步都先测后调，而不是先调后测。失败模式里“INT4 权重未保留异常值通道，实时率提升但关键词识别失败率上升”正是跳过第二步的直接后果：少数大幅值通道量化后矩阵乘结果偏移，省下的带宽被关键词回退吃掉。工程判断是：端侧配方的可复现性不来自参数本身，而来自参数与观测量之间的绑定关系——每个量化决策都必须有一个对应的准确率或实时率观测量作为门禁，否则配方在换设备、换语种、换噪声环境时不可迁移。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-31\">三十一 · 配方失效的三个边界：校准漂移、KV 累积误差与 INT4 异常值</h3>\n<p>这套配方在实验室安静环境下能跑通，不代表在端侧真实场景成立。第一个失效条件是校准集与部署分布的错位：校准集若以近场、低噪、标准口音为主，各层激活动态范围被估窄，端侧噪声段激活会溢出裁剪区间，量化误差在噪声帧上被放大，实时率反而掩盖了准确率劣化。工程上必须把校准集按噪声类型与口音分层采样，并在部署后用少量无标注语音做在线动态范围监控——一旦某层激活的裁剪比例超过阈值，就回退该层到高精度通道。第二个失效条件是解码器 KV cache 的低比特累积：自回归解码每一步都读取历史 KV，低比特存储的舍入误差随解码步数单调累积，长语音的句尾准确率明显低于句首，且误差不可通过输出反量化消除。第三个失效条件是 INT4 权重量化未保留异常值通道，少数大幅值通道量化后矩阵乘结果整体偏移，表现为实时率提升但关键词识别失败率上升。</p>\n<p>系统代价必须按比特数折算而非按直觉估计。权重与 KV 的显存占用近似随比特数线性下降，但激活在线量化引入逐帧裁剪与缩放计算，端侧单流批大小为 1 时这部分开销无法被批处理摊薄，直接计入每帧延迟。设编码器单帧矩阵乘的 FP16 计算量为 $C$，低比特路径的有效吞吐提升受指令利用率约束，端侧实时率近似为：</p>\n<div class=\"formula\">$$\\text{RTF} \\approx \\frac{t_{\\text{quant}} + t_{\\text{mma}}(b) + t_{\\text{kv}}(b_{\\text{kv}})}{T_{\\text{frame}}}$$</div>\n<p>其中 $t_{\\text{quant}}$ 为激活在线量化开销，$t_{\\text{mma}}(b)$ 为低比特矩阵乘时间，$t_{\\text{kv}}(b_{\\text{kv}})$ 为 KV 读取时间，$T_{\\text{frame}}$ 为帧块时长。INT4 路径下 $t_{\\text{mma}}$ 与 $t_{\\text{kv}}$ 下降，但 $t_{\\text{quant}}$ 与异常值通道的混合精度分支上升，净收益取决于异常值通道占比——占比高时混合精度分支频繁触发，实时率收益被抵消。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测现象</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>校准集分布偏窄</td><td>噪声段识别劣化</td><td>准确率下降，实时率虚高</td><td>分层校准 + 在线裁剪监控</td></tr><tr><td>KV 低比特无补偿</td><td>句尾准确率低于句首</td><td>长语音准确率累积损失</td><td>KV 分块滚动 + 关键层保留高精度</td></tr><tr><td>INT4 未保留异常值</td><td>关键词失败率上升</td><td>混合精度分支增加延迟</td><td>异常值通道单独高精度处理</td></tr></tbody></table>\n<p>边界判断应落在具体机制上：端侧单流、批大小为 1 的流式识别，INT8 权重加 INT8 KV 是默认安全档位，实时率收益稳定且异常值处理简单；INT4 只在异常值通道占比可控、且长语音场景可接受 KV 分块滚动补偿时启用。校准集必须覆盖真实噪声与口音，否则实时率提升只是把误差从计算路径转移到了识别结果上——这是配方能否复现的分界线，而非精度数字本身。</p>\n<h3 id=\"alg-asr-quant-edge-sec-32\">三十二 · 显存墙：权重、KV cache 与滚动窗口的三方挤压</h3>\n<p>端侧 ASR 的显存账本从来不是单一变量。编码器权重、解码器权重、解码器 KV cache、激活工作区、音频帧块缓冲，这五项在 FP16 下各自占据可观的字节数，而量化只对其中前三项有直接杠杆。按比特数近似线性下降的是权重与 KV cache 的静态占用；激活工作区受低比特矩阵乘的累加器精度约束，通常不会同比例缩小——INT8 矩阵乘的累加仍在 INT32 或 FP32 上完成，激活在线量化的临时缓冲反而可能因为要保留异常值通道而膨胀。这就是端侧部署里第一个先崩的地方：不是总算力不够，而是静态权重与动态 KV cache 争抢同一块固定显存。</p>\n<p>KV cache 的账要按块滚动来算。设解码器层数为 $L$、注意力头数为 $H$、头维度为 $d$、每帧块产生 $T$ 个 token、KV 以 $b_{kv}$ 比特存储，则单帧块的 KV 增量近似为 $2 \\cdot L \\cdot H \\cdot d \\cdot T \\cdot b_{kv}/8$ 字节（因子 2 来自 K 与 V 两份）。INT4 存储把这个增量压到 FP16 的四分之一，但长语音下滚动窗口的容量上限并不随比特数线性放宽——因为窗口一旦滚出，被丢弃的历史 KV 无法再参与注意力，识别准确率在句尾开始掉。工程上的判断是：KV cache 低比特化的收益主要体现在“同样窗口能装更长历史”，而不是“同样历史能装更小窗口”；把这两者混为一谈，就会在长语音上遇到句尾准确率显著低于句首的失败模式。</p>\n<p>具体例子：一个端侧流式识别会话按帧块输入，批大小固定为 1 以控制延迟。权重 INT4 后编码器与解码器静态占用下降，但解码器 KV cache 若仍按 FP16 滚动，长语音下它会成为唯一持续增长的显存项，最终触发滚动丢弃而非量化压缩。此时正确动作是把 KV 也降到 INT4 并配合误差补偿，而不是继续加大滚动窗口。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-33\">三十三 · 带宽：低比特真正买到的是读带宽，不是算力</h3>\n<p>端侧推理的瓶颈分布与数据中心相反。数据中心里矩阵乘的算力密度往往压过带宽，端侧则是内存读带宽先见底：解码器自回归每步只处理一个 token，矩阵乘的算术强度极低，性能几乎完全由“把权重从显存读进计算单元”的速度决定。这正是低比特量化在端侧的核心价值——权重按比特数近似线性降低读带宽需求，INT4 相对 FP16 把每步解码的权重读取量压到四分之一，实时率的提升主要来自这里，而非来自 Tensor Core 的峰值算力。</p>\n<p>用公式表达这个约束：设某层权重元素数为 $N$、比特数为 $b$、显存读带宽为 $B$，则该层权重读取时间下界为 $t \\ge N \\cdot b / (8B)$。解码一步的总时间近似为各层该下界之和加上激活量化与反量化的开销。激活在线量化本身要读一遍激活、写一遍量化结果、再读一遍做反量化，这部分开销在低比特下占比上升，成为新的带宽项。逐通道对称量化的形式为</p>\n<div class=\"formula\">$$q=\\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{x}{s}\\big),\\,-2^{b-1},\\,2^{b-1}-1\\Big),\\quad \\hat{x}=s\\cdot q$$</div>\n<p>其中 $s$ 为逐通道缩放因子，$b=8$ 或 $4$。注意 $s$ 的逐通道粒度意味着每个通道要额外读一个缩放因子，通道数多时这笔元数据带宽不可忽略；把缩放因子打包进权重布局、与量化值同块读取，是端侧实现里必须做的布局优化。</p>\n<p>具体例子：解码器某层权重在 FP16 下每步读取量对应的时间下界，在 INT4 下缩为四分之一，但该层激活在线量化的读写往返在总时间中的占比从次要项升为主要项。此时继续压权重比特（比如尝试更激进的格式）收益递减，而把激活量化的动态范围裁剪做紧、减少异常值通道的单独处理路径，才是下一步的带宽优化点。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-34\">三十四 · 通信：端侧单流拓扑下，通信代价藏在流水边界</h3>\n<p>端侧 ASR 的并行拓扑是编码器与解码器流水、端侧单流，没有跨卡集合通信，但这不等于没有通信代价。流水边界上的激活传递、帧块缓冲的搬运、量化与反量化之间的格式转换，都是实打实的数据移动。编码器输出送解码器时要经过一次反量化（若编码器输出也低比特存储），解码器输出再反量化送语言模型或后处理；每一次反量化都是一次读带宽事件，且发生在流水关键路径上，直接计入尾延迟。</p>\n<p>把流水边界的形式写清楚：设编码器每帧块输出张量元素数为 $M$、以 $b_{a}$ 比特存储、边界带宽为 $B_{l}$，则边界搬运时间下界为 $M \\cdot b_{a}/(8B_{l})$。低比特化把这个下界压低，但反量化后的张量若以 FP16 进入解码器，实际搬运量又回到高位——所以边界优化的关键不是“存得低”，而是“算得低”：让解码器的第一层矩阵乘直接消费量化格式，把反量化融进矩阵乘的加载路径，避免物化一份 FP16 中间张量。</p>\n<p>具体例子：端侧单流下，编码器与解码器流水重叠的程度决定了尾延迟。若边界上物化 FP16 中间张量，流水重叠被这次物化打断，帧块处理的尾延迟出现尖峰；若把反量化融进解码器首层的加载，边界只剩量化格式的搬运，流水可以连续推进。这个差别在平均延迟上看不出来，在尾延迟上非常明显。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-35\">三十五 · 功耗：比特数、激活量化开销与实时率的三角</h3>\n<p>端侧离线语音助手以实时率与功耗衡量 SLO，而这两者并不总是同向。降低权重比特数减少显存读带宽，通常降低动态功耗；但激活在线量化引入额外的读写与算术，异常值通道保留高精度又引入混合精度路径，这些都会推高单位帧块的能耗。更微妙的是实时率与功耗的关系：为了压低尾延迟而提高时钟或并行度，功耗上升；为了省电而降频，实时率余量被吃掉，尾延迟变差。低比特量化的正确用法是在固定功耗预算下换实时率余量，而不是同时追求两者。</p>\n<p>粗略的能耗模型可以写成 $E \\approx E_{w} + E_{a} + E_{mm}$，其中 $E_{w}$ 正比于权重读取字节数（随 $b$ 线性下降），$E_{a}$ 正比于激活量化的读写往返（随异常值处理复杂度上升），$E_{mm}$ 正比于低比特矩阵乘的运算量（INT4 相对 INT8 在同样运算量下能耗更低，但端侧解码的运算量本就很小，这一项占比有限）。工程判断是：当 $E_{a}$ 的增长超过 $E_{w}$ 的节省时，继续压比特数反而恶化功耗，此时应停在 INT8 并把异常值处理做轻。</p>\n<p>具体例子：INT4 权重未保留异常值通道时，少数大幅值通道量化后矩阵乘结果偏移，实时率提升但关键词识别失败率上升——为了补救而加回异常值高精度路径，$E_{a}$ 上升，功耗优势被侵蚀。这说明 INT4 的功耗收益必须以异常值处理的高效实现为前提，否则账面收益兑现不了。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-36\">三十六 · 尾延迟：规模上去以后第一个崩的是它</h3>\n<p>端侧批大小为 1，平均延迟好看不代表尾延迟好看。尾延迟的来源有三类：帧块边界上的流水气泡、激活异常值触发的混合精度慢路径、以及长语音下 KV cache 滚动丢弃后的重新对齐。规模上去（会话变长、噪声段变多、口音分布变宽）时，这三类同时放大，而平均延迟可能几乎不变——这就是“规模上去以后哪里先崩”的答案：先崩的是尾延迟，不是吞吐，也不是显存。</p>\n<p>尾延迟的放大机制可以这样看：设单帧块处理时间为 $t_{i}$，尾延迟关注的是高分位数 $\\max$ 附近的 $t_{i}$。低比特量化把 $t_{i}$ 的基线压低，但异常值通道的混合精度路径让 $t_{i}$ 的方差变大；基线低、方差大，高分位数反而可能比 FP16 更差。校准集未覆盖真实噪声与口音时，激活动态范围估计偏窄，端侧部署后量化误差在噪声段放大，噪声段恰好触发更多异常值慢路径，尾延迟与准确率同时劣化。</p>\n<p>具体例子：一段带突发噪声的长语音，噪声段激活幅值超出校准得到的动态范围，裁剪后量化误差放大，同时异常值通道被频繁触发走混合精度路径，该帧块的 $t_{i}$ 明显高于安静段。若按平均延迟做容量规划，这段会话会被判为达标，但用户体验上出现可感知的卡顿。正确做法是按帧块延迟的高分位数做 SLO 校验，并把激活动态范围裁剪与异常值阈值一起纳入校准。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-37\">三十七 · 规模上限的工程判断：先保准确率方差，再谈比特数</h3>\n<p>把上述四项代价放在一起，规模上限的约束顺序是清楚的：显存决定能装多长历史，带宽决定每步解码的下界，功耗决定实时率余量，尾延迟决定用户体验的方差。低比特量化对这四项的杠杆并不均等——它对带宽最有效，对显存次之（受 KV cache 滚动语义约束），对功耗有条件有效（取决于激活量化开销），对尾延迟则可能反向。因此规模上去后先崩的是尾延迟与长语音句尾准确率，而不是显存或算力。</p>\n<p>工程判断落在两件事上。第一，比特数选择应以准确率方差而非平均准确率为准：INT4 权重需异常值保留，实现复杂度高于 INT8，若异常值处理路径不能做轻，INT8 加紧动态范围裁剪在尾延迟与功耗上更稳。第二，KV cache 低比特存储必须配误差补偿，否则长语音自回归解码误差逐步累积，句尾识别准确率显著低于句首——这个失败模式在规模上去后最先暴露，且无法靠加显存解决，因为问题在数值而不在容量。</p>\n<p>最后落到具体机制：把校准集的覆盖范围（真实噪声与口音）与激活在线量化的动态范围裁剪绑定成同一个可调参数，按帧块延迟高分位数与句尾准确率两个指标联合调参，而不是分别调。这个绑定让“实时率提升但准确率劣化”的失败模式在部署前就可观测，是把低比特量化从账面收益兑现为端侧稳定收益的最小工程动作。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-38\">三十八 · 规模上去以后，先崩的是解码 KV cache 的读带宽而不是算力</h3>\n<p>端侧 ASR 的批大小被钉死在 1 或极小批以控制尾延迟，这意味着矩阵乘单元长期处于低占用状态，真正决定实时率的不是 Tensor Core 的峰值算力，而是每帧块解码步必须从内存搬进芯片的字节数。把权重压到 INT4 后，权重流量按比特数近似线性下降，但自回归解码每步都要重读整条 KV cache，序列越长这部分流量占比越高。设层数 $L$、隐藏维 $d$、头数 $h$、每头维度 $d_h$、比特数 $b_{kv}$，长 $T$ 的语音在解码第 $t$ 步需读取的 KV 字节约为 $2L\\cdot T\\cdot h\\cdot d_h\\cdot b_{kv}/8$，它与 $T$ 成正比而与批大小无关——这正是单流端侧场景下最先触顶的墙。用逐通道对称量化描述这一步的存储精度：</p>\n<div class=\"formula\">$$q=\\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{x}{s}\\big),\\,-2^{b-1},\\,2^{b-1}-1\\Big),\\quad \\hat{x}=s\\cdot q,\\quad s=\\frac{\\max|x|}{2^{b-1}-1}$$</div>\n<p>KV cache 走 INT8 时读带宽减半，走 INT4 时再减半，但 $s$ 是按通道（通常按头或按通道组）统计的，长语音里不同帧块的激活动态范围漂移，早期帧块估出的 $s$ 到句尾已不再匹配，误差在自回归链上逐步累积，表现为句尾识别准确率显著低于句首。工程上的对策是按块滚动 KV cache 并周期性重估缩放因子，代价是每块边界多一次同步与重算，尾延迟出现锯齿；若不做误差补偿而直接 INT4 存储，实时率提升换来的是长语音准确率下降，这是该方案最典型的失效条件。</p>\n<h3 id=\"alg-asr-quant-edge-sec-39\">三十九 · 功耗墙与异常值通道的实现税</h3>\n<p>边缘 SKU 的功耗预算是硬约束，低比特矩阵乘用 DP4A 或低比特 Tensor Core 指令确实降低了单次乘加的能耗，但端侧流式识别是持续负载而非突发负载，功耗取决于平均带宽而非峰值算力。权重 INT4 加激活在线量化把权重流量压到 FP16 的四分之一，可激活在线量化本身要读一遍 FP16 激活、算动态范围、再写回低比特，这段额外流量在小模型上占比不可忽略；当模型被量化到能塞进更小显存档位时，收益才真正兑现，否则只是把带宽从权重搬到了激活侧。更隐蔽的代价是异常值通道：少数大幅值通道必须保留高精度或单独走一条 FP16 通路，实现上意味着矩阵乘被切成两段、多一次掩码与拼接，指令发射与寄存器压力上升，INT4 相对 INT8 的复杂度税在这里体现得最清楚。校准集未覆盖真实噪声与口音时，激活动态范围估计偏窄，噪声段的量化误差被放大，实时率上去了而准确率塌下来——这类失败在离线语音助手的实际口音分布下比在朗读测试集上更早暴露。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先触顶的资源</th><th>典型表现</th></tr></thead><tbody><tr><td>语音时长增长</td><td>KV cache 读带宽</td><td>句尾准确率下降、尾延迟锯齿</td></tr><tr><td>模型层数/宽度增长</td><td>权重流量与显存档位</td><td>量化后仍放不进目标 SKU</td></tr><tr><td>异常值通道比例上升</td><td>指令与寄存器</td><td>混合精度分支拖慢矩阵乘</td></tr><tr><td>噪声/口音分布偏移</td><td>校准有效性</td><td>实时率达标、关键词识别失败率上升</td></tr></tbody></table>\n<p>因此容量规划要按“最长语音 × 最坏口音”而非平均帧块来定 KV cache 档位与缩放因子重估周期，把 INT4 权重留给编码器这类一次前向、流量集中的部分，解码器 KV cache 保守停在 INT8 并配误差补偿，才是端侧单流拓扑下不先崩的配置。</p>\n<h3 id=\"alg-asr-quant-edge-sec-40\">四十 · 精度塌陷的三种形态与可观测信号</h3>\n<p>端侧 ASR 的低比特推理失败，很少表现为“整体 WER 均匀上升”，而是按段、按帧、按 token 位置非均匀塌陷。工程上要先把塌陷拆成三种可分辨的形态，否则监控面板上一条聚合曲线无法定位根因。第一种是<strong>噪声段放大</strong>：校准集未覆盖真实噪声与口音，激活动态范围估计偏窄，端侧部署后量化误差在噪声段被放大，识别准确率明显下降。其信号特征是安静段 WER 正常、噪声段 WER 跳变，且与输入信噪比呈负相关。第二种是<strong>KV cache 累积漂移</strong>：解码器 KV cache 低比特存储未做误差补偿，长语音自回归解码误差逐步累积，句尾识别准确率显著低于句首。信号特征是同一句内 token 位置的错误率随位置单调上升，且换气/静音切块后错误率回落。第三种是<strong>异常值通道失守</strong>：INT4 权重未保留异常值通道，少数大幅值通道量化后矩阵乘结果偏移，实时率提升但关键词识别失败率上升。信号特征是关键词命中率单独下降，而通用字错率变化不明显——因为异常值通道往往对应少数高能量特征维度，恰好承载唤醒词与命令词的判别信息。</p>\n<p>三种形态对应三种不同的量化误差来源，可用同一套量化公式区分：</p>\n<div class=\"formula\">$$q=\\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{x}{s}\\big),\\,-2^{b-1},\\,2^{b-1}-1\\Big),\\quad \\hat{x}=s\\cdot q,\\quad s=\\frac{\\max|x|}{2^{b-1}-1}$$</div>\n<p>噪声段放大来自 $s$ 在激活维度上被校准集的窄动态范围低估，导致真实噪声激活越界被 clip；KV cache 漂移来自 $q$ 在长序列上反复反量化再量化，误差不归零而累加；异常值通道失守来自 $\\max|x|$ 被单个大幅值通道主导，其余通道的有效位被压缩。诊断的第一步不是看总指标，而是把 $s$ 的逐通道分布、clip 比例、以及反量化残差 $\\|x-\\hat{x}\\|$ 按层、按帧位置打点上报。</p>\n<p>系统代价上，这三种塌陷的修复成本差异极大：噪声段放大只需重做校准集，代价是离线一次前向统计；KV cache 漂移需要引入误差补偿或提高 cache 位宽，直接抬高自回归解码的显存读带宽；异常值通道失守需要在权重离线阶段做通道级混合精度，增加实现复杂度但不增加运行时算力。监控设计必须能把这三者分开计数，否则回滚决策会打错靶子。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-41\">四十一 · OOM 与批抖动的耦合诊断</h3>\n<p>端侧流式识别的批大小通常为 1 或小批以控制延迟，因此 OOM 不是“批太大”这么简单，而是<strong>显存峰值与帧块滚动策略错配</strong>。编码器按帧块流式前向，解码器 KV cache 低比特存储并按块滚动以控制显存；一旦滚动边界与解码步数不同步，KV cache 会在某个解码步瞬时超出预留窗口，触发 OOM。诊断要点是把显存占用按“权重常驻 + 激活瞬时 + KV cache 滚动窗口 + 反量化临时缓冲”四段拆开打点，而不是只看进程级显存总量。反量化临时缓冲常被忽略：低比特矩阵乘输出反量化后送语言模型/后处理，若反量化在 kernel 内未做原地复用，会额外申请一份与激活同尺寸的 FP16 缓冲，在小显存边缘 SKU 上足以把峰值顶穿。</p>\n<p>批抖动则是 OOM 的近邻症状。端侧请求形态是流式帧块输入，块到达间隔受麦克风采集与 VAD 切分影响，批形成窗口内的块数抖动会直接改变单次前向的激活尺寸。当系统为了压尾延迟而动态放大批，激活瞬时段膨胀，与 KV cache 滚动窗口叠加后触发 OOM；OOM 后框架回退到更小批，又造成延迟尖刺。这是一个正反馈环，表现为周期性的“批放大—OOM—回退—尖刺”。诊断方法是记录每次前向的批内块数、激活字节数、KV 窗口占用与是否发生回退，把回退事件与批大小序列对齐，确认抖动是外部到达抖动还是内部调度策略引起的放大。</p>\n<p>工程判断上，端侧不应追求批吞吐，而应把批形成窗口固定为与帧块周期对齐的常量，让激活瞬时段可预测；KV cache 滚动窗口按最长语句的上界预留，宁可牺牲一点常驻显存也不做动态扩张。这样 OOM 从随机事件变成可静态核算的容量问题，批抖动也随之消失。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-42\">四十二 · 路由不均与尾延迟尖刺</h3>\n<p>在端侧单流拓扑下，“路由不均”不是多副本负载均衡问题，而是<strong>编码器与解码器流水之间的工作量分配不均</strong>。编码器按帧块做低比特矩阵乘，工作量与块长成正比且可预测；解码器自回归逐步生成，工作量与已生成 token 数成正比且随语句长度增长。当一句话进入后半段，解码器每步都要读更长的低比特 KV cache，读带宽随位置线性上升，而编码器仍在稳定输出帧块——流水后端成为瓶颈，尾延迟尖刺出现在长句末尾。这与第一部分讲的句尾准确率下降同源，但表现为延迟而非精度。</p>\n<p>诊断信号是分阶段延迟直方图：把每帧块的编码耗时、每解码步的 KV 读耗时、反量化与后处理耗时分别打点，观察 P99 落在哪一段。若 P99 集中在解码步且随 token 位置上升，则是 KV 读带宽问题；若集中在编码段且与块长相关，则是低比特矩阵乘的指令利用率问题。可用如下伪代码思路做在线归因：</p>\n<ul>\n<li>对每个请求记录 (块序号, 编码耗时, 解码步序号, KV 读字节, 反量化耗时)；</li>\n<li>按 token 位置分桶聚合 P50/P99，若 P99 桶位随位置单调右移，标记为 KV 带宽型尖刺；</li>\n<li>若编码段 P99 与块长强相关而均值平稳，标记为指令利用型尖刺，检查 DP4A/Tensor Core 路径是否被异常值通道的混合精度分支打断；</li>\n<li>把标记结果与回退事件对齐，区分尖刺是容量不足还是调度策略触发。</li>\n</ul>\n<p>系统代价上，KV 带宽型尖刺的修复要么提高 cache 位宽（牺牲显存与带宽），要么引入分块预取把读带宽摊平（增加实现复杂度）；指令利用型尖刺的修复通常是异常值通道的分离处理路径，避免混合精度分支在热路径上反复切换。两者都不应通过放大批来掩盖，端侧的 SLO 以实时率与功耗衡量，放大批只会把尖刺换成 OOM。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-43\">四十三 · 监控指标体系与打点位置</h3>\n<p>端侧低比特 ASR 的监控不能照搬数据中心的服务指标。可用的事实约束是：SLO 以实时率与功耗衡量，硬件档位为 Blackwell 边缘 SKU，量化方案为权重 INT8/INT4 离线量化加激活在线量化，异常值通道保留高精度或混合精度。据此，监控应分三层打点。第一层是<strong>量化健康度</strong>：逐层上报激活 clip 比例、逐通道 $s$ 的分布偏移、反量化残差范数，以及异常值通道的命中计数。第二层是<strong>运行时资源</strong>：四段显存拆分、KV 滚动窗口占用率、低比特矩阵乘的指令吞吐、反量化缓冲峰值。第三层是<strong>质量代理</strong>：按噪声段/安静段、按 token 位置分桶的字错率与关键词命中率，以及句首与句尾的准确率差。</p>\n<p>打点位置要贴着机制步骤走，而不是贴着框架 API 走。校准集前向统计阶段就要留存每层动态范围，部署后把在线激活的实际动态范围与校准值比对，偏移超过阈值即标记为分布不匹配；权重离线量化阶段留存异常值通道清单，运行时统计这些通道是否走了高精度分支；KV cache 低比特存储的每一步读写都记录位宽与补偿标志，用于区分漂移是位宽不足还是补偿缺失。质量代理不能只算整句 WER，必须按位置分桶，否则句尾漂移会被句首的正确识别稀释。</p>\n<table class=\"mini\"><thead><tr><th>失败形态</th><th>主信号</th><th>打点位置</th><th>代价维度</th></tr></thead><tbody><tr><td>噪声段放大</td><td>噪声段 WER 跳变、clip 比例上升</td><td>激活在线量化入口</td><td>准确率</td></tr><tr><td>KV 漂移</td><td>错误率随 token 位置单调上升</td><td>KV cache 读写</td><td>长语音准确率、读带宽</td></tr><tr><td>异常值失守</td><td>关键词命中率单独下降</td><td>权重离线量化 + 混合精度分支</td><td>实现复杂度、实时率</td></tr><tr><td>OOM</td><td>四段显存峰值顶穿</td><td>反量化缓冲与 KV 窗口</td><td>显存</td></tr><tr><td>批抖动</td><td>回退事件与批大小序列对齐</td><td>批形成窗口</td><td>尾延迟</td></tr><tr><td>路由不均</td><td>分阶段 P99 随位置右移</td><td>编码段与解码步</td><td>尾延迟、功耗</td></tr></tbody></table>\n<p>指标体系的工程判断是：宁可少而可归因，不要多而聚合。端侧算力与功耗预算有限，监控本身也要低开销——采样打点而非全量打点，质量代理用固定小测试集周期性回放而非实时全量比对。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-44\">四十四 · 回滚策略：分级降级而非一刀切</h3>\n<p>回滚不是“切回 FP16”这一个动作。端侧低比特推理的失败模式粒度很细，一刀切回 FP16 会同时丢掉实时率与功耗收益，在离线语音助手场景下可能直接不可用。合理的回滚是分级降级，每一级对应一种失败形态。第一级是<strong>校准重做</strong>：针对噪声段放大，用覆盖真实噪声与口音的校准集重新统计动态范围，只更新 $s$ 与异常值通道清单，权重位宽不变，代价是离线一次前向，运行时零开销。第二级是<strong>KV 位宽提升或补偿开启</strong>：针对句尾漂移，把解码器 KV cache 从低比特提升一档或打开误差补偿标志，代价是显存读带宽上升，实时率略降。第三级是<strong>异常值通道强制高精度</strong>：针对关键词失守，把清单内通道切回高精度分支，代价是实现路径分支增多、指令利用率下降。第四级才是<strong>整层或整模型回退到 INT8/FP16</strong>，作为兜底。</p>\n<p>分级回滚的触发条件必须与监控信号绑定，且要有滞回避免抖动。例如噪声段 WER 相对基线偏移超过阈值并持续若干帧块才触发第一级；句尾与句首准确率差超过阈值才触发第二级；关键词命中率单独下降才触发第三级。回滚动作本身要可观测：记录降级级别、触发信号、降级后的实时率与功耗变化，形成闭环。工程上还要预留“回滚预算”——端侧功耗与实时率 SLO 决定了最多能承受几级降级，超过预算就必须走第四级兜底，而不是继续在细粒度上修补。</p>\n<p>一个具体例子：某离线语音助手在噪声环境下关键词识别失败率上升，而通用字错率平稳。按指标体系，异常值通道命中计数下降、关键词命中率分桶下降，触发第三级回滚，把异常值通道切回高精度；实时率略降但仍在 SLO 内，功耗上升可接受。若同时观察到句尾准确率差扩大，则叠加第二级 KV 补偿。两级叠加后若实时率跌破 SLO，才进入第四级整模型回退。这个顺序保证每次降级都对准一个已归因的失败形态，而不是用精度换稳定性的盲目交易。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-45\">四十五 · 诊断闭环与工程判断</h3>\n<p>把上述内容收束成一个可执行的诊断闭环：校准阶段留存逐层动态范围与异常值通道清单；部署阶段按四段显存、分阶段延迟、分桶质量三层打点；运行阶段用分桶信号归因到三种精度形态、OOM/批抖动、路由不均中的一种；归因结果驱动分级回滚，回滚后的实时率与功耗变化回写预算表。闭环的关键是<strong>信号与机制一一对应</strong>，任何一条监控曲线若不能指向一个具体机制步骤（校准、权重离线量化、激活在线量化、KV 低比特存储、反量化后处理），就不应进入告警面板。</p>\n<p>工程判断上，端侧低比特 ASR 的稳定性上限由低比特量化误差与 KV cache 累积误差约束，长语音与分布外口音下准确率下降是结构性的，不能靠调参消除。因此诊断的目标不是“消灭失败”，而是“让失败可归因、可分级、可预算”。INT4 权重需异常值保留，实现复杂度高于 INT8，这意味着 INT4 部署必须自带异常值通道的运行时分支与监控，否则实时率提升会被关键词失守悄悄抵消。最终落在具体机制上：逐通道缩放因子 $s$ 的在线偏移监测、KV cache 每步读写位宽与补偿标志的记录、异常值通道高精度分支的命中计数，这三条打点是端侧低比特推理能否稳住的工程底线。</p>\n<h3 id=\"alg-asr-quant-edge-sec-46\">四十六 · 同族算法的选择维度：比特宽度不是唯一轴</h3>\n<p>在端侧 ASR 的量化选型里，把“INT8 还是 INT4”当作唯一决策变量是最常见的误判。真正决定成败的是三个正交维度：权重比特宽度、激活量化策略（静态还是在线动态）、以及 KV cache 是否随权重一同降比特。三者对系统代价的作用点完全不同——权重比特决定模型常驻显存与首帧加载时间，激活策略决定每帧块的计算图是否引入额外裁剪与缩放开销，KV cache 比特决定长语音下的显存读带宽与误差累积斜率。一个 INT4 权重 + FP16 激活 + FP16 KV cache 的组合，显存收益只落在权重上，自回归解码的读带宽瓶颈几乎没动；反之 INT8 权重 + INT8 在线激活 + INT8 KV cache 的组合，带宽收益覆盖全链路，但异常值处理复杂度上升。选型的第一步是把这三条轴拆开，分别对照 SLO 中的实时率、功耗上限与长语音准确率约束，而不是笼统地问“能不能再低一比特”。</p>\n<p>量化映射本身在所有同族方案中共享同一形式：</p>\n<div class=\"formula\">$$q=\\mathrm{clip}\\Big(\\mathrm{round}\\big(\\tfrac{x}{s}\\big),\\,-2^{b-1},\\,2^{b-1}-1\\Big),\\quad \\hat{x}=s\\cdot q,\\quad s=\\frac{\\max|x|}{2^{b-1}-1}$$</div>\n<p>差别不在公式，而在 $s$ 的粒度（逐张量、逐通道、逐组）与 $\\max|x|$ 的统计来源（离线校准集还是运行时滑动窗口）。逐通道缩放是端侧 ASR 的默认基线，因为编码器卷积与注意力的输出通道动态范围差异显著；逐组缩放（group-wise）在 INT4 下几乎必需，否则单通道内的少数大幅值会把整组有效位宽吃掉。工程判断是：INT8 用逐通道即可，INT4 必须落到组粒度并配合异常值通道保留，否则实时率提升会被关键词识别失败率抵消。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-47\">四十七 · 与 FP16 基线的对照：线性收益与非线性代价</h3>\n<p>相对 FP16 端侧 ASR，低比特量化的显存与带宽收益近似按比特数线性下降：权重从 16 bit 降到 8 bit，常驻显存减半；降到 4 bit 再减半。这条线性关系在权重侧成立得很好，因为权重是离线静态的，缩放因子可预先烘焙进权重布局，推理时无额外统计开销。但代价是非线性的：激活异常值导致的量化误差不随比特数平滑变化，INT8 到 INT4 之间存在一个明显的准确率台阶，尤其在噪声段与分布外口音上。系统代价的体现是，INT4 带来的显存节省换来的可能是编码器前几层特征图的信噪比下降，而这一下降在流式按帧块识别时表现为噪声帧的置信度抖动，后处理语言模型需要更多纠错预算。</p>\n<p>具体例子：一个端侧流式识别负载，批大小为 1、按帧块输入，SLO 以实时率与功耗衡量。若把解码器 KV cache 从 FP16 降到 INT8，长语音的自回归解码读带宽下降，实时率改善；但若同时把权重压到 INT4 而未保留异常值通道，少数大幅值通道的矩阵乘结果偏移，表现为句尾识别准确率显著低于句首——这是 KV cache 低比特存储未做误差补偿时误差逐步累积的典型形态。因此与 FP16 对照的正确结论不是“越低越好”，而是“权重可激进、KV cache 需保守、激活需按分布校准”。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-48\">四十八 · 与 SmoothQuant 类均衡方法的对照：作用点不同</h3>\n<p>SmoothQuant 类激活-权重均衡方法的着力点是把激活的异常值通过等价变换迁移到权重侧，使激活的动态范围收窄、更易量化。它解决的是“激活难量化”这一侧的问题，通常不触及 KV cache 的存储格式，也不以端侧 DP4A/Tensor Core 指令利用与功耗约束为首要目标。本族方法的着力点是端侧低比特权重与 KV cache 量化，强调在 Blackwell 边缘 SKU 上用低比特 Tensor Core 或 DP4A 指令把矩阵乘做实，并把解码器 KV cache 一并降比特以削减自回归解码的显存读带宽。两者的选择条件是：若瓶颈在激活量化的准确率损失且权重可保持较高比特，均衡方法更直接；若瓶颈在端侧显存容量、功耗墙与解码读带宽，本族方法覆盖更完整。二者可以叠加——先做均衡把激活范围压窄，再做逐通道/逐组低比特量化——但叠加会增加校准与实现复杂度，端侧单流流水下每帧块的额外缩放开销需要计入实时率预算。</p>\n<p>代价对照要落到具体资源上：均衡方法引入的是推理图上的逐通道缩放乘法，属于算力开销；本族方法的 KV cache 低比特化引入的是反量化读路径，属于带宽与精度开销。前者在算力紧张的边缘 SKU 上更贵，后者在长语音、大 KV cache 场景下更敏感。选型时先测瓶颈落在哪一侧，再决定叠加顺序。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-49\">四十九 · 决策表：按场景条件选型</h3>\n<table class=\"mini\"><thead><tr><th>场景条件</th><th>权重</th><th>激活</th><th>KV cache</th><th>关键代价</th></tr></thead><tbody>\n<tr><td>离线语音助手，短指令，功耗墙紧</td><td>INT8 逐通道</td><td>INT8 在线</td><td>INT8</td><td>校准覆盖不足时噪声段误差放大</td></tr>\n<tr><td>端侧长语音听写，显存受限</td><td>INT4 逐组 + 异常值保留</td><td>INT8 在线</td><td>INT8 带误差补偿</td><td>KV cache 累积误差，句尾准确率下降</td></tr>\n<tr><td>关键词唤醒/命令词，实时率优先</td><td>INT4 逐组</td><td>INT8 在线</td><td>不适用（短帧）</td><td>异常值通道未保留则关键词失败率上升</td></tr>\n<tr><td>分布外口音多，准确率优先</td><td>INT8 逐通道</td><td>FP16 或 INT8 静态</td><td>FP16</td><td>显存与带宽收益收窄，功耗上升</td></tr>\n<tr><td>激活异常值突出，权重可放宽</td><td>INT8</td><td>均衡后 INT8</td><td>INT8</td><td>推理图缩放乘法增加算力开销</td></tr>\n</tbody></table>\n<p>表的读法是按约束排序而非按比特排序：功耗墙紧且语音短，优先把权重与 KV cache 都压到 INT8，激活在线量化保证分布漂移下的鲁棒；长语音听写必须给 KV cache 留误差补偿预算，否则累积误差会在句尾暴露；命令词场景帧短、无长自回归，KV cache 一项可跳过，把复杂度留给异常值通道保留。分布外口音多的场景应主动放弃 INT4 权重，因为校准集与真实分布不匹配时实时率提升但准确率劣化，这是本族方法最典型的失败路径。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-50\">五十 · 适用条件与规模上限的工程判断</h3>\n<p>适用边界由两条曲线夹住：一条是量化误差随比特数下降的准确率曲线，一条是显存带宽随比特数下降的实时率曲线。两条曲线的交点位置取决于校准集质量与异常值比例，而不是硬件规格。工程上可操作的判据是：校准集必须覆盖真实噪声与口音，激活动态范围裁剪要留足余量，异常值通道保留高精度或单独处理；满足这三条，INT8 全链路（权重、激活、KV cache）在端侧单流流水下是稳态可交付的配置。INT4 权重只在异常值通道保留到位、且语音段长度可控时成立，规模上限受低比特量化误差与 KV cache 累积误差约束，长语音与分布外口音下准确率下降是结构性而非偶发的。</p>\n<p>部署配方上，编码器与解码器流水、端侧单流意味着没有批维度来摊薄量化开销，每帧块的在线激活量化与反量化都直接计入实时率。因此选型时应把“每帧块的反量化读路径长度”作为一等指标：KV cache 低比特存储降低读带宽，但反量化本身消耗算力，二者在功耗墙紧的 SKU 上会互相抵消。稳定性技巧的优先级是校准集覆盖 &gt; 异常值通道保留 &gt; 激活动态范围裁剪，因为前两者决定误差的量级，后者只决定误差的分布。最终落在具体机制上的判断是：先固定 KV cache 的比特与误差补偿策略，再决定权重能否下探到 INT4——顺序反了，实时率的收益会被句尾准确率的回退吞掉。</p>\n\n<h3 id=\"alg-asr-quant-edge-sec-51\">五十一 · 边界判定：同族量化路线在端侧 ASR 上的取舍与失效面</h3>\n<p>把本方案放进同族算法谱系里，真正要回答的不是“谁更先进”，而是“在端侧单流、批大小为 1、以实时率和功耗为 SLO 的约束下，哪条路线的误差预算还能守住”。三条相邻路线各有明确的适用条件。FP16 端侧 ASR 是精度基线：无校准、无异常值处理、无 KV cache 量化误差累积，代价是权重与激活按 16 bit 占用显存、矩阵乘走 FP16 通路，端侧只能跑较小模型或抬高功耗；它适用于口音分布外、长语音、关键词召回敏感的场景。SmoothQuant 类激活-权重均衡方法把激活的离群幅值迁移到权重通道上，缓解激活在线量化的动态范围压力，但它本身不解决 KV cache 的低比特读带宽问题，也不以 DP4A/Tensor Core 低比特指令的利用率为设计中心；它适用于激活离群显著、但仍以 FP16/INT8 混合精度矩阵乘为主、功耗约束不极端的部署。本方案则把重心放在权重 INT8/INT4 离线量化、激活在线量化、KV cache 低比特存储三件事同时落地，用逐通道缩放与异常值通道保留换取端侧显存带宽与算力的近似线性下降，适用于离线语音助手这类低功耗、单流、按帧块流式识别的形态。三者的分界不在算法优劣，而在“误差预算被谁吃掉”：FP16 吃掉显存与功耗，SmoothQuant 吃掉实现复杂度但保留较高比特矩阵乘，本方案吃掉校准质量与长语音稳定性。</p>\n<p>决策时可用一个粗略的误差-代价判据：设权重与激活比特数为 $b_w$、$b_a$，KV cache 比特数为 $b_{kv}$，则单帧显存读带宽近似正比于 $b_w N_w + b_a N_a + b_{kv} N_{kv}$（$N$ 为对应元素数），而端到端实时率受矩阵乘吞吐与解码自回归串行性共同支配。量化带来的收益是这一带宽项的线性收缩，代价是量化误差 $\\lVert \\hat{W}-W\\rVert$ 在噪声段与长语音上的累积。判据是：当校准集覆盖真实噪声与口音、且异常值通道被保留高精度时，INT8 权重加 INT8 激活加低比特 KV cache 是可守的默认档；只有当显存或功耗硬约束逼迫降到 INT4 权重时，才需要额外付出异常值通道单独处理的实现复杂度。反过来说，若校准集与真实分布不匹配，激活动态范围估计偏窄，端侧部署后量化误差会在噪声段被放大，出现实时率提升但识别准确率明显下降的典型失效——此时应退回 FP16 或 SmoothQuant 路线，而不是继续压比特。</p>\n<p>具体到失效条件，三条边界必须写进部署检查单。其一，INT4 权重未保留异常值通道时，少数大幅值通道量化后矩阵乘结果整体偏移，表现为实时率提升而关键词识别失败率上升，这类失效在安静环境下不易暴露，只在噪声段与远场条件下显现。其二，解码器 KV cache 低比特存储若不做误差补偿，长语音自回归解码误差逐步累积，句尾识别准确率显著低于句首，因此长语音必须按块滚动控制显存，并对 KV cache 采用更高比特或保留关键通道。其三，编码器与解码器流水、端侧单流拓扑下，激活在线量化的动态范围裁剪若过于激进，会在突发噪声帧上截断有效动态范围。系统代价方面，本方案换来的是显存占用与带宽按比特数近似线性下降、低比特矩阵乘在 Blackwell 边缘 SKU 上可利用专用指令提升实时率，付出的是校准集构建、异常值通道识别与混合精度分支的实现复杂度，以及 INT4 档位下准确率与实时率之间的强耦合。工程判断落在这一点：端侧 ASR 的量化档位应由“校准集是否覆盖真实噪声与口音”和“长语音 KV cache 误差是否可补偿”两个条件共同决定，而不是由峰值实时率单独决定。</p>\n<table class=\"mini\"><thead><tr><th>路线</th><th>适用条件</th><th>主要代价</th><th>典型失效</th></tr></thead><tbody><tr><td>FP16 端侧 ASR</td><td>分布外口音、长语音、关键词召回敏感</td><td>显存与功耗高，模型规模受限</td><td>实时率不达标</td></tr><tr><td>SmoothQuant 类均衡</td><td>激活离群显著、功耗约束不极端</td><td>实现复杂度，KV cache 未降比特</td><td>解码读带宽仍为瓶颈</td></tr><tr><td>本方案（INT8/INT4 + 低比特 KV）</td><td>离线语音助手、单流、按帧块流式</td><td>校准与异常值处理复杂度</td><td>噪声段误差放大、句尾准确率下降</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 自回归与非自回归声学建模</td></tr><tr><td>解决什么</td><td>语音识别模型在边缘/端侧部署时显存与算力受限，FP16 权重与激活占用大，实时率与功耗难以满足离线语音助手需求。</td></tr><tr><td>一句话机制</td><td>对 ASR 编码器/解码器做低比特（INT8/INT4）权重量化与激活量化，配合逐通道缩放与异常值保留，降低显存带宽与…</td></tr><tr><td>代价与失效</td><td>激活异常值导致量化误差，需保留通道或做混合精度，增加实现复杂度；低比特解码 KV cache 可能累积误差，长语音识别准确率下降</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-asr-quant-edge · 共 8 个片段</p>\n";break;}}})();
